window.HARDTRP.receive("36440",[[36441,"2026-06-09T21:22:19",9,"Начало темы.\n\n@elsio28  Дм этой темы.",36440,null],[36442,"2026-06-09T21:24:46",5,"Квест «Родовой меч»\nДля 2-3 игроков любого уровня. Опасность: лёгкая, потому что в худшем случае вы попадёте в тюрьму и заплатите штраф. Стелс-приключение в чьём-то особняке. Золота много не ждите, всё зависит от ваших навыков клептомании.\n\nАвантюристы передают друг другу полученную неизвестным способом записку со следующим текстом:\n«Ищу сметливых героев, готовых вернуть украденную фамильную реликвию, меч моего отца. Найдите меня у таверны \"Большой башмак\", буду сидеть на скамейке с цветком за ухом. Дело деликатное, не привлекайте много внимания.»\n\nКвест планируется на четверг 12:00.\nХБ персонажей не беру. От игроков требуется пунктуальность.\n\nУчастники:\n1.@Heyhoft  https://t.me/c/3239766844/613/615\n2.@QURTZZ https://t.me/c/3239766844/785",36440,null],[36454,"2026-06-09T21:39:41",5,"Особые правила для квеста:\n1. Скорость всех персонажей на территории особняка снижена в 2 раза. Из-за узких коридоров и мебели.\n2. Буду описывать обстановку комнат, насколько смогу, но вы можете сами придумывать предметы мебели и их использование. Это поощряется.\n3. Двери могут быть закрыты\n4. Основной добычей будет всякая утварь в доме. Опять же, можете придумывать и отыгрывать как вы стащили что-то",36440,null],[36886,"2026-06-10T13:08:15",5,"Итак, игра будет завтра в 13:00. Всем удобно? @Heyhoft @QURTZZ",36440,null],[36887,"2026-06-10T13:20:19",31,"Мне нормально",36440,null],[36890,"2026-06-10T13:29:45",10,"Окей пусть в час",36440,null],[37963,"2026-06-11T12:59:44",9,"//А ты орочи не идёшь повозку защищать?",36887,null],[37964,"2026-06-11T13:01:02",5,"// начну в течение 5 минут",36440,null],[37970,"2026-06-11T13:06:17",5,"// у нас пополнение",36440,null],[37971,"2026-06-11T13:06:29",31,"сегодня тут, завтра там",37963,null],[37972,"2026-06-11T13:06:56",9,"//Предлагаю кинуть артики и описания персов перед началом ^^",36440,null],[37973,"2026-06-11T13:07:37",5,"Таверна \"Большой башмак\", к которой отправились герои, находится в городе-государстве Аннежь. Один из городов, основанных после катаклизма, он слывёт весьма бюрократичным местом. Власть находится в руках множества чиновников, и за соблюдением закона следят очень пристально.\n\nГерои обнаруживают себя у входа в таверну. Из неё выходят очень подозрительные типы. С такими с одним столом пить небезопасно. Опишите, кто находится перед входом.",36440,null],[37974,"2026-06-11T13:08:02",11,"// мяу я имею ввиду игого",37970,null],[37975,"2026-06-11T13:08:47",31,"огромный голый нага (если не считать веревки на поясе). Несмотря на свои размеры кадется довольно ловким и быстрым",37973,null],[37976,"2026-06-11T13:09:07",5,"// 4 игрока итого) если все здесь",36440,null],[37977,"2026-06-11T13:09:22",9,"//Арт персонажа\n\n*Леда был человеком, или эльфом, он не помнит. Выглядит как человек, ближе к маленькому великану по размерам, но ниже пояса большой круглый ком плоти из конечностей из которого растёт верхняя часть его тела.*\n\n*Рост 8,1 фута (247 см). Вес 413 фунтов (187 кг). Глаза золотистые. Тёмные, растрёпанные волосы ниспадают на плечи. На вид крепкий и стройный, по крайней мере верхняя половина.*\n\n*На плечах короткая накидка (мантия). Ниже пояса обвязан верёвкой, на которой закреплён сундук, десять мешков и одеяло. Таким образом он закрывает последствия проклятия от глаз чужих.*",36440,null],[37978,"2026-06-11T13:11:18",11,"// идеальный подбор персов под стелс",36440,null],[37979,"2026-06-11T13:11:24",9,"*Маленький великан пригнувшись кое как протискивается в проход таверны. Первым делом медленно будто плывёт по таверне меж столов подвигая плотно заставленные стулья. Намерен купить себе поесть.*\n\n//-1 золотой думаю, ему порция что 2 рациона",36440,null],[37980,"2026-06-11T13:11:39",9,"//Тут Иштар ещё?)))",37978,null],[37981,"2026-06-11T13:11:40",10,"*Рури ебун колдун. Становлюсь невидимым и люблю сомнительные сделки*",36440,null],[37982,"2026-06-11T13:12:01",9,"//4 самых крупных персонажа на сервере в 1 месте!!!",36440,null],[37983,"2026-06-11T13:12:24",31,"// Орочи решает что в таверне булет тесно если еще и он зайдет. так что просто просовывается окно",36440,null],[37984,"2026-06-11T13:12:25",5,"В таверне великану быстро подают огромное вкусно пахнущее блюдо. Уплетая его за обе щеки, он вспоминает, что место встречи было назначено на улице.",37979,null],[37985,"2026-06-11T13:12:42",10,"// это вы кстати лохи я умею уменьшаться и становиться невидимым",37982,null],[37986,"2026-06-11T13:13:46",10,"*Иду к великану... который ниже меня на 3 сантиметра* - я подсяду ?",36440,null],[37987,"2026-06-11T13:13:58",9,"*Леда все равно сначала нормально поел прежде чем прийти в назначенное место.*\n\n//Я так понял, наниматель на самом деле хочет чтобы мы разыбали родовое поместье или чёт такое. Иначе бы не нанял 4 великанов ^^",37984,null],[37988,"2026-06-11T13:14:34",5,"На скамейке  недалеко от таверны спиной к героям сидит какой-то парень. На первый взгляд совершенно заурядный. Однако при взгляде на него в голову лезут мысли, что такой стащит кошелёк, перережет горло, а когда ты оберёшься — сзади будет пусто. Вы отгоняете эти мысли.\n\nУ него за ухом немного увядший цветок герани.",36440,null],[37989,"2026-06-11T13:14:42",9,"*Смотрит на тебя, он редко видит тех кро примерно его роста. Просто кивает.*",37986,null],[37990,"2026-06-11T13:14:58",5,"// окей герои пока могут познакомиться в таверне)",36440,null],[37991,"2026-06-11T13:15:08",5,"// сразу видно кто на дело идёт",36440,null],[37992,"2026-06-11T13:16:05",31,"_ может нам предстоит проникнуть в замок огра каокго нибудь и мы там будем незаметны?",36440,null],[37993,"2026-06-11T13:16:18",10,"-я сама незаметность",36440,null],[37994,"2026-06-11T13:17:22",5,"Какой-то скользкий тип, проходящий мимо, сказал.\n\n— В Аннеже нет замков огров. Земля дорогая",37992,null],[37995,"2026-06-11T13:17:37",11,"Придя к таверне темнокожий кентавр осматривался в поисках человека с цветком в волосах\n— Почему именно у таверны? Выпил бы, да перед работой нельзя.. — тихо размышлял он вслух пока его внимание не привлек нужный человек \nДоверия он не внушал, но Иштар подошёл поздороваться\n— Ну здравствуй, человек с цветком — слышит парень над собой, в то время как его закрывает огромная тень",37988,null],[37996,"2026-06-11T13:18:28",9,"//Я не понимаю где некоторые персы, рядом Леду сверлит взглядом Рури а кентавр тусуется снаружи",36440,null],[37997,"2026-06-11T13:18:52",31,"_ какжется тут нет человека с цветком, поищем снаружи может?",36440,null],[37998,"2026-06-11T13:19:27",10,"*Кормлю демоническую лошадку* - кушай кушай вырастешь таким же большим как я",36440,null],[37999,"2026-06-11T13:19:33",5,"В окно таверны остальные герои отлично видят происходящее на улице. Кентавр подошёл к юноше с цветком и что-то произнёс. Тот молча встал, кинул внимательный взгляд в окно таверны, прямо на вас, и медленно пошёл в темный проулок.",36440,null],[38000,"2026-06-11T13:19:43",5,"// ещё лошадь притащил, хдд",37998,null],[38001,"2026-06-11T13:19:46",10,"-Идем видимо это к нам",36440,null],[38002,"2026-06-11T13:20:00",9,"— Почти доел. — *Коротко сказал Леда, и быстро доел что оставалось в миске вымочив остатки ломтём хлеба вышел наружу искать того самого челока.*",37997,null],[38003,"2026-06-11T13:20:03",10,"//это игрушечный демонический единорог",36440,null],[38004,"2026-06-11T13:20:19",10,"*Иду в темный переулок с Ледой*",36440,null],[38005,"2026-06-11T13:20:21",11,"// не переживай коня издалека найдешь",38002,null],[38006,"2026-06-11T13:20:35",31,"*скольжу в переулок*",36440,null],[38007,"2026-06-11T13:20:40",11,"// Хард, я бы побоялась с огромным фембоем в переулок ходить..",38004,null],[38008,"2026-06-11T13:21:27",5,"В конце узкого переулка видно, как парень открывает дверь, входит в неё и оставляет открытой. Это выглядит как приглашение.",36440,null],[38009,"2026-06-11T13:21:40",5,"// все кидайте спас ловкости или мудрости",36440,null],[38010,"2026-06-11T13:21:45",9,"//У меня есть огромный дрын и у леды ниже пояса просто сросшийся конечности и запчасти тел, там нечего некуда и все такое. Проклятый же",38007,null],[38011,"2026-06-11T13:21:45",5,"// сл 10",36440,null],[38012,"2026-06-11T13:21:57",10,"/r 1d20+2",36440,null],[38013,"2026-06-11T13:22:27",10,"... сломалась скотобаза чтоль?\\\\",36440,null],[38015,"2026-06-11T13:22:43",31,"/r +3",38009,null],[38019,"2026-06-11T13:23:08",5,"// ну отлично... кидайте через другого бота если умеете хз(",36440,null],[38020,"2026-06-11T13:23:19",9,"/roll 1d20+1",36440,null],[38021,"2026-06-11T13:23:28",9,"//Пардон...",36440,null],[38022,"2026-06-11T13:23:47",5,"// ладно все прошли",36440,null],[38023,"2026-06-11T13:23:59",9,"//Чё за нах",36440,null],[38024,"2026-06-11T13:24:03",10,"//роллбот тоже умер",36440,null],[38025,"2026-06-11T13:24:08",9,"/roll@roll_bot",36440,null],[38027,"2026-06-11T13:24:20",9,"//Уууу, сюка...",36440,null],[38028,"2026-06-11T13:24:30",5,"Где-то наверху кто-то опрокидывает ведро. Густая струя помоев падает прямо в переулок. По счастью, все герои оказываются достаточно внимательны, чтобы не испачкаться.\n\nДверь ждёт впереди.",36440,null],[38031,"2026-06-11T13:24:54",11,"Наклоняясь что бы не поздороваться лбом с рамой двери кентавр зашёл следом за парнем",38028,null],[38032,"2026-06-11T13:25:47",31,"*заползаю в дверь*",38028,null],[38033,"2026-06-11T13:26:28",10,"*уменьшаюсь до нормального размера человека и захожу спокойно *",36440,null],[38034,"2026-06-11T13:26:34",9,"*Кое как залез внутрь прохода, видно что с трудом.*",36440,null],[38035,"2026-06-11T13:26:56",5,"// пока текстовая часть, надеюсь бот починится позже",36440,null],[38037,"2026-06-11T13:27:09",11,"— Здесь становится тесно — подмечает мужчина",36440,null],[38044,"2026-06-11T13:29:07",5,"Вы видите большую комнату, весьма пустую. Посередине стоит большой стол, в одном углу стул и шкаф за ним. По краям комнаты лежит какой-то хлам.\n\nЗа столом стоит тот самый юноша и приветливо смотрит на вас.\n\n— Приветствую, спасибо за помощь! Извините за эту таинственность, в Аннеже стражи правопорядка могут подслушивать даже в тавернах. А наше дело нелегальное, хоть и морально честное",36440,null],[38045,"2026-06-11T13:29:59",10,"-Крадем у богатых отдаем бедным нам?",36440,null],[38046,"2026-06-11T13:30:07",5,"— Я начну со своей истории, чтобы ни у кого не было моральных колебаний. Но сначала познакомимся. Меня зовут Карс. \n\nОн приветливо машет всей компании",36440,null],[38047,"2026-06-11T13:30:08",11,"Иштар кивал внимательно слушая, думая лишь о том зачем парень залез на стол",36440,null],[38050,"2026-06-11T13:31:06",10,"-Рури *показываю лошадку* - а это Уаз Хантер",36440,null],[38061,"2026-06-11T13:32:47",11,"— Иштар — придерживая шлем в руках коротко произнес он",36440,null],[38068,"2026-06-11T13:35:54",9,"//Короче, я хрен знает как в этом боте сделать преимущество/помеху, поэтому просто кидайте два куба. Если прошлый не оживёт то чтош, будет так ~",36440,null],[38069,"2026-06-11T13:37:17",9,"— Леда. — *Коротко назвал себя гигант и скрестил руки на груди. Привыкший быть высоким среди низких сейчас он чувствовал себя немного неуюно, но не показывал этого.*",36440,null],[38070,"2026-06-11T13:37:35",5,"— В нашем роду уже много поколений передаётся один меч. От прадеда к деду, от деда к отцу. Мой отец был солдатом на службе славного города Аннежа. Несколько лет назад он погиб в битве, сражаясь этим родовым мечом. Однако, когда его нашли после битвы, меча рядом не было. По крайней мере, так сказал командир отделения.",36440,null],[38071,"2026-06-11T13:39:03",11,"Кажется Иштар наоборот стал чувствовать себя комфортнее. Проведя несколько лет среди людей и прочих рас меньше его самого ему приятно было не выделяться",38069,null],[38072,"2026-06-11T13:39:38",5,"— С тех пор командир этот здорово продвинулся по службе, стал военным советником, построил здоровенный особняк. Часто устраивает балы. И вот недавно я услышал от знакомого, бывавшего у него, что хозяин хвастался гостям своим мечом. И меч по описанию точь в точь как родовой меч нашей семьи.\n\nГлаза Карса недобро сверкнули. Он вспоминает подробности и злится.",36440,null],[38073,"2026-06-11T13:40:48",5,"— Я пришёл к выводу, что командир украл меч после боя. И теперь хранит его у себя в доме. Я этого просто так не оставлю!",36440,null],[38075,"2026-06-11T13:41:10",11,"— Ты уверен что это ваш меч? Ты ведь даже не видел его",36440,null],[38077,"2026-06-11T13:42:24",5,"— Уверен. Меня в тот дом не пустят, ясное дело. Но знакомый описал меч. Описание совпало. А ведь он не был знаком с моим отцом, не видел родовой меч семьи раньше.",38075,null],[38078,"2026-06-11T13:42:59",11,"— Хорошо, у тебя есть какой-то план?",36440,null],[38079,"2026-06-11T13:43:10",31,"- а какие у меча отличительные признаки? это ведь может быть меч от того же старого мастера",36440,null],[38080,"2026-06-11T13:43:23",10,"-да что за меч хоть и где он может его хранить?",36440,null],[38081,"2026-06-11T13:43:49",5,"— О да, у меня есть план. Трудился над ними ночами! — юноша горделиво выпрямился",38078,null],[38082,"2026-06-11T13:44:33",5,"— Руны на лезвии, небольшой изумруд на эфесе. Вы сразу узнаете. Хранит он меч в собственном кабинете, на 3 этаже особняка",38079,null],[38083,"2026-06-11T13:45:32",5,"— Надеюсь, вопросы по моральной стороне моей просьбы исчезли?",36440,null],[38084,"2026-06-11T13:46:27",10,"-у меня не было итак вопросов) я просто хочу залезть куда тооо",36440,null],[38085,"2026-06-11T13:46:36",11,"— Я не вор, но готов помочь вернуть твое.",36440,null],[38086,"2026-06-11T13:47:24",31,"- я ысе еще в небольшом сомнении, верить на слово без доказательтс права владения...",36440,null],[38087,"2026-06-11T13:48:48",5,"— Я понимаю. Меч я описал, сам увидишь. тот он или нет, как попадёшь внутрь.",38086,null],[38088,"2026-06-11T13:49:38",31,"я не сомневаюсь что узнаю. но чем ты докажешь что не просто хочешь украсть чужое имущество?",38087,null],[38089,"2026-06-11T13:49:51",9,"— Скрывать гордость семьи — глупость. Укравши ворами прослыли они коль многим известно. Теперь вор ты, вознёсшийся достояние своё чужими. — *Леда имел своё мнение поэтому поводу, но от предложения не отказывался.* — Помочь — согласен.",36440,null],[38090,"2026-06-11T13:49:59",11,"// вообще он может врать что меч его и просто хотеть украсть меч командира, но мой перс не настолько проницательный",36440,null],[38091,"2026-06-11T13:50:37",9,"//Я могу попробовать бросить на проницательность, моё чудо должно быть мудрым + -",36440,null],[38092,"2026-06-11T13:51:05",5,"Карс покачал головой.\n\n— Дело было давно, знакомые отца уже умерли, кто на войне, кто от старости. Боюсь, у меня нет прямых доказательств",38088,null],[38093,"2026-06-11T13:51:16",31,"//я тоже могу, у меня +4 к проницательности",38091,null],[38094,"2026-06-11T13:51:54",10,"-Богатыми честно не становятся. Давайте тоже разбогатеем чутьчуть",36440,null],[38095,"2026-06-11T13:52:11",11,"// отыграйте, мой перс не подвергает слова квестодателя сомнению",36440,null],[38096,"2026-06-11T13:52:41",5,"// сам не могу разобраться что это значит",38089,null],[38097,"2026-06-11T13:53:26",9,"//Надо гордится достоянием своей семьи. Если бы о их мече было известно многим то и доказательства бы не пришлось искать а теперь красть меч)",38096,null],[38098,"2026-06-11T13:54:06",9,"//Типа, шас для общего мнения ворами теперь будут они, ведь меч видели не у них)))",36440,null],[38099,"2026-06-11T13:54:12",10,"-Пойдемте пойдемте но было бы круто если бы вы сняли это шумящую броню",36440,null],[38100,"2026-06-11T13:54:18",31,"//ладно, будем считать что я прочел в глазах парня честность",36440,null],[38101,"2026-06-11T13:54:40",9,"//Я без доспехов ^^",38099,null],[38104,"2026-06-11T13:55:00",10,"//сейчас ночь ?",36440,null],[38108,"2026-06-11T13:55:12",9,"//Оооо, курва, заработал!",36440,null],[38110,"2026-06-11T13:55:43",9,"//Надеюсь збс будет, играем!",36440,null],[38111,"2026-06-11T13:55:47",5,"— Моя семья никогда не была известной или богатой, родовой меч был главной ценностью",38089,null],[38112,"2026-06-11T13:56:07",5,"// нет, утро-день",38104,null],[38113,"2026-06-11T13:56:20",11,"// послушайте план пацана, ребят",36440,null],[38114,"2026-06-11T13:56:23",5,"— Тогда перейдём к плану. Хотите послушать с начала или с конца?\n\nКарс достаёт какие-то чертежи из шкафа. Вы видите, что там полно бумаг и каких-то свитков.",36440,null],[38115,"2026-06-11T13:56:38",10,"-давай рассказывай *Садится*",36440,null],[38116,"2026-06-11T13:57:35",9,"*Присесть Леде не судьба... он прислонился к одной из стен, слушает и смотрит.*",36440,null],[38117,"2026-06-11T13:58:04",9,"*Просто молча кивнул.*",38111,null],[38118,"2026-06-11T13:58:41",5,"// ты занял единственный стул)",38115,null],[38119,"2026-06-11T13:59:04",10,"*хлопаю по коленкам*",36440,null],[38120,"2026-06-11T14:00:31",9,"//Наге Мне и кентавру не нужен стул, для справки. Леде лично не сесть, он модет ток стоять или лежать или полулёжа. Команда мечты ^^",36440,null],[38121,"2026-06-11T14:00:43",5,"— Хорошо, тогда вот наш план. Во-первых, я не останусь в стороне. Привезу вас к месту на телеге, и буду ждать, как вы выберетесь. Кони что запряжены быстрее, чем кажутся.",36440,null],[38122,"2026-06-11T14:00:50",11,"// я выносливый, постою",36440,null],[38123,"2026-06-11T14:01:19",10,"-пока план хороший...",38121,null],[38124,"2026-06-11T14:01:23",11,"— Окей, а что дальше?",38121,null],[38125,"2026-06-11T14:01:39",31,"телега должна быть очень большая...",38121,null],[38126,"2026-06-11T14:02:22",9,"//Ахпаххх. Вес Леды 187 кг, Нага 350 кг, кентавр и фэмбой? Что там за бронетранспортёр!)))",36440,null],[38127,"2026-06-11T14:02:24",5,"—У главного входа всегда стоит стража, там не пройти. Однако, крыша первого этажа легкодоступна. И там есть труба. Через неё вы попадёте в столовую.\n\nКарс показывает на трубу на листе.",36440,null],[38128,"2026-06-11T14:02:44",5,"// это план второго этажа",36440,null],[38129,"2026-06-11T14:02:46",11,"// я своим ходом)",38126,null],[38131,"2026-06-11T14:03:23",11,"Кажется парень ловит на себе странные взгляды от всех кроме Рури",38127,null],[38132,"2026-06-11T14:03:27",9,"//Бля ребят, лезем в трубу!",36440,null],[38133,"2026-06-11T14:03:31",5,"— Вот столовая на первом этаже\n\nЮноша указывает на большую комнату в нижней части плана",36440,null],[38134,"2026-06-11T14:04:16",11,"— Стоп-стоп, боюсь залезть по трубе у нас не получится, ну по крайней мере у троих из нас — Иштар указал обеими руками на двоих крупных спутников, а затем на себя",36440,null],[38135,"2026-06-11T14:04:18",5,"Карс сразу почувствовал озадаченные взгляды.\n\n— Не беспокойтесь о своих размерах, товарищи. У меня в запасе есть отличные свитки, они нам помогут",38131,null],[38136,"2026-06-11T14:04:22",9,"*Леда переглядывается с остальными когда речь идёт о повозке и трубе. Но молчит.*",36440,null],[38137,"2026-06-11T14:04:48",5,"Юноша достаёт несколько свитков уменьшения размера из шкафа.",36440,null],[38138,"2026-06-11T14:05:14",11,"// а у меня уже была идея другой план предложить",36440,null],[38139,"2026-06-11T14:05:29",10,"-Ты прям подготовился",36440,null],[38140,"2026-06-11T14:05:39",5,"// на месте можно действовать иначе)",38138,null],[38141,"2026-06-11T14:06:04",11,"— Даже если я буду меньше я не смогу карабкаться, приятель",38135,null],[38142,"2026-06-11T14:06:05",10,"-С этим свитком я смогу стать как полурослик",36440,null],[38143,"2026-06-11T14:06:07",5,"— Конечно. У нас будет одна попытка. Не получится сейчас — и мой меч потерян навсегда",38139,null],[38144,"2026-06-11T14:06:52",31,"применишь два свитка и мы тебя в кармане донесем//",38141,null],[38145,"2026-06-11T14:07:12",11,"// Инсайд, вот тебе последняя модель УАЗа",38144,null],[38146,"2026-06-11T14:07:39",5,"— Надо лишь запрыгнуть на крышу первого этажа. И там как раз есть хорошее место для прыжка",38141,null],[38147,"2026-06-11T14:07:54",10,"//шикарно",38145,null],[38148,"2026-06-11T14:08:02",9,"*Леда поднял руку.*\n\n— Есть ли ощущаюший магию среди нас? Простой сигнал тревоги разоблачит весь план.",36440,null],[38149,"2026-06-11T14:08:22",10,"- я умею колдоваать *Поднимаю руку*",36440,null],[38150,"2026-06-11T14:08:31",11,"— Я плохо разбираюсь в магии, но великан прав",36440,null],[38151,"2026-06-11T14:09:16",5,"— Не волнуйтесь, хозяин не готов. Скажу больше, он как раз сегодня проводит очередной приём в соседнем особняке, тоже его. Так что прислуга и большая часть охраны будут там.",38148,null],[38152,"2026-06-11T14:09:17",10,"// у меня есть обнаружение магии одно до короткого",36440,null],[38153,"2026-06-11T14:09:32",10,"-Отличная новость",38151,null],[38154,"2026-06-11T14:09:43",10,"-А у тебя случайно нет свитка незримой поступи?",36440,null],[38155,"2026-06-11T14:09:52",11,"// было бы забавно притвориться гостями",38151,null],[38156,"2026-06-11T14:10:05",5,"// хорошая идея, да...",38155,null],[38157,"2026-06-11T14:10:06",9,"— Хорошие для нас новости.",38151,null],[38158,"2026-06-11T14:10:15",5,"— Чего нет, того нет",38154,null],[38159,"2026-06-11T14:11:05",11,"Кентавр присматривается к карте\n— Где здесь комната в которой меч?",38127,null],[38160,"2026-06-11T14:11:10",10,"-хорошо... а план 3го этажа есть? там ведь находится его кабинет",36440,null],[38161,"2026-06-11T14:11:23",5,"— Дальше к плану. Ваша цель — винтовая лестница, по ней можно добраться до третьего этажа.",36440,null],[38162,"2026-06-11T14:12:14",5,"А вот здесь, — Карс показывает на следующий чертёж — Его кабинет. И меч там же.",36440,null],[38163,"2026-06-11T14:12:42",10,"-агаа ладно можно попробовать",36440,null],[38164,"2026-06-11T14:13:00",5,"— До этого момента шуметь не стоит. Но как только меч в ваших руках — дело в шляпе. Открываете окно на третьем этаже и спрыгиваете по крышам прямо ко мне. А там помчимся!",36440,null],[38165,"2026-06-11T14:13:13",10,"-звучит весело",36440,null],[38166,"2026-06-11T14:13:43",31,"_ если все так просто, то зачем ты собрал аж четверых? у одиночного вора разве не больше шансов пройти незаметно?",36440,null],[38167,"2026-06-11T14:14:44",5,"— Справедливое замечание. Я отправил записку с просьбой и не знал, сколько найдётся желающих. А теперь выгонять будет попросту неприлично",38166,null],[38168,"2026-06-11T14:15:12",11,"// просто чтобы нам веселее было",38166,null],[38169,"2026-06-11T14:15:14",10,"-Как думаешь много стражи останется внутри?",36440,null],[38170,"2026-06-11T14:15:42",10,"-Типа если мы знаем общее количество стражи то можно посмотреть сколько сейчас на его приеме в соседнем доме",36440,null],[38171,"2026-06-11T14:15:53",9,"— Четыре маленьких вора — большая кража. Не ищет никто четыре крупных фигуры.",36440,null],[38172,"2026-06-11T14:16:15",5,"— Немного, но ребята крепкие. Двое всегда стоят снаружи, ещё несколько внутри. И дам вам совет — ни в коем случае не убивайте стражу.",38169,null],[38173,"2026-06-11T14:16:27",11,"// насколько крепкие?",36440,null],[38174,"2026-06-11T14:16:31",11,"// есть просто у меня идея..",36440,null],[38175,"2026-06-11T14:16:58",5,"// это стелс миссия, весьма крепкие",38173,null],[38176,"2026-06-11T14:17:02",5,"// делай",38174,null],[38177,"2026-06-11T14:17:12",11,"// тогда не получится, эх",36440,null],[38178,"2026-06-11T14:17:36",11,"— У тебя нет запасной брони похожей на ту что носят стражники случаем?",36440,null],[38179,"2026-06-11T14:17:48",5,"Карс кивнул.\n\n— Очень мудро",38171,null],[38180,"2026-06-11T14:17:57",10,"-Окей не убивать и все такое...  Давайте подождем начала приема и пойдем тогда на дело",36440,null],[38181,"2026-06-11T14:18:11",31,"согласен",38180,null],[38182,"2026-06-11T14:18:11",11,"— Пора выдвигаться полагаю?",36440,null],[38183,"2026-06-11T14:18:26",5,"Юноша хитро прищурился.\n\n— Мне нравится твоя идея. Пожалуй, один комплект найду",38178,null],[38184,"2026-06-11T14:19:10",11,"// честно хотелось попробовать вырубить одного и снять с него броню, это было бы в духе перса больше чем просто притворяться стражником",36440,null],[38185,"2026-06-11T14:19:39",10,"- я умею усыпять но думаю смогу только одного",36440,null],[38186,"2026-06-11T14:19:59",5,"Карс достаёт из шкафа и отдаёт кентавру немного потрепанный Чешуйчатый доспех.",36440,null],[38187,"2026-06-11T14:20:32",10,"-еще у меня есть отличная штука. *показываю серебряные столовые приборы, которыми король ел в свой последний раз *",36440,null],[38188,"2026-06-11T14:20:48",10,"-Если поесть с этими приборами то человек отравится",36440,null],[38189,"2026-06-11T14:20:57",11,"— Так будет лучше чем совсем без брони.. если понадобится я смогу подстраховать вас сказав прислуге что делаю обход или типа того — задумчиво произнес мужчина",36440,null],[38190,"2026-06-11T14:21:01",10,"//сам придумал сам мучайся хард)",36440,null],[38191,"2026-06-11T14:21:02",5,"— Не думаю, что у вас будет время кормить стражу",38187,null],[38192,"2026-06-11T14:21:40",10,"//предлагаю магию монтажа и перенестись в начало приема",36440,null],[38193,"2026-06-11T14:21:46",9,"//Я бы предложил после того как найдем меч поджечь особняк чтобы им не до нас было. Но перс простой в этом плане как палка",36440,null],[38194,"2026-06-11T14:21:59",10,"//я такое люблю",36440,null],[38195,"2026-06-11T14:22:02",5,"// пхпх жёстко) Можете",38193,null],[38196,"2026-06-11T14:22:03",11,"// это надо каким персом играть что бы такой хаос наводить)) мой будет против, да и думаю нага тоже",38193,null],[38197,"2026-06-11T14:22:18",10,"\\\\Нейтральным )",36440,null],[38198,"2026-06-11T14:22:20",5,"// окей",38192,null],[38199,"2026-06-11T14:22:48",9,"//Я делаю наёмника вместо Даэрана, он будет использовать все методы)))",36440,null],[38200,"2026-06-11T14:23:24",10,"//Итак у нас какие свитки есть?",36440,null],[38201,"2026-06-11T14:23:52",9,"//Уменьшение на концентрации, наверное 10 минут",36440,null],[38202,"2026-06-11T14:24:05",10,"//не повезло вам) у меня природное",36440,null],[38203,"2026-06-11T14:24:13",5,"// свиток требует концентрации?",38201,null],[38204,"2026-06-11T14:24:36",9,"//Ещё и наличия уровня в классе заклинателя который умеет накладывать уменьшение, но не будем душнить",36440,null],[38205,"2026-06-11T14:24:59",10,"//Заклинание в свитке",38203,null],[38206,"2026-06-11T14:25:13",9,"//Решает дм короче что и как",36440,null],[38207,"2026-06-11T14:25:31",10,"//Магия монтажа мой Патрон помог вам наложить эти заклинания чтобы повеселиться",38204,null],[38208,"2026-06-11T14:26:12",5,"Герои  выходят на улицу и садятся в телегу, кто может. Юноша везёт вас по всё более богатым кварталами города, вскоре вы останавливаетесь у богатого особняка. На крышу можно залезть совершенно незаметно. \n\nКарс использует один из свитков уменьшения на наге, затем достаёт ещё 2 зелья уменьшения размера.",36440,null],[38210,"2026-06-11T14:27:20",5,"// окей, вы на крыше первого этажа",36440,null],[38211,"2026-06-11T14:27:21",31,"*удивленно осматриваю себя, я  таким мелким не был с момента вылупления из яйца*",38208,null],[38212,"2026-06-11T14:27:52",10,"*прислушиваюсь к трубе  есть ли звуки с кухни*",36440,null],[38213,"2026-06-11T14:28:08",10,"/r 1d20+2",36440,null],[38215,"2026-06-11T14:28:49",11,"// насколько мы мелкие кстати",36440,null],[38216,"2026-06-11T14:29:11",10,"//я как обычный человек размером. Вы уменьшились на один размер тоесть делите на 2",36440,null],[38217,"2026-06-11T14:29:21",5,"Рури чётко слышит голос кухарки. Она о чём-то ворчит, затем слышен хлопок двери. Больше звуков нет.\n\nСтража у двери о чём-то лениво разговаривает.",38212,null],[38218,"2026-06-11T14:29:37",10,"уменьшение. Размеры цели уменьшаются вдвое по всем измерениям, а вес уменьшается до одной восьмой от обычного. \\\\",36440,null],[38219,"2026-06-11T14:30:06",10,"*показываю большой палец и акуратно лезу внутрь*",36440,null],[38220,"2026-06-11T14:30:10",9,"*Леда взглянул на особняк.*\n\n— Обвязать верёвку вокруг дымохода. Взглянуть в окно третьего этажа или залезть. — *Леда высказал вслух первую свою идею когда увидел особняк со стороны.*",36440,null],[38221,"2026-06-11T14:30:37",11,"— Мне его идея нравится больше чем пробираться внутри",36440,null],[38222,"2026-06-11T14:31:07",31,"*заглядываю в трубу, жду что напарник залезет, после чего протинусь сам*",38219,null],[38223,"2026-06-11T14:31:11",10,"\\\\... хм я думаю я изнутри зайду",36440,null],[38224,"2026-06-11T14:31:15",10,"// я же невидимка",36440,null],[38225,"2026-06-11T14:31:19",11,"// сплит?",36440,null],[38226,"2026-06-11T14:31:48",9,"— Меча может не быть здесь. Если владелец хвастает им на празднецтве.",36440,null],[38227,"2026-06-11T14:32:44",5,"// можно",38225,null],[38228,"2026-06-11T14:33:02",10,"//жаль нет лесниц у вас",36440,null],[38230,"2026-06-11T14:33:44",31,"чисто теоритичеки я могу выполнить роль каната//",38228,null],[38231,"2026-06-11T14:34:05",10,"//вы можете идти по верху спокойно я изнутри зайду",36440,null],[38232,"2026-06-11T14:34:08",10,"//окно открою",36440,null],[38235,"2026-06-11T14:34:38",9,"//Вообще идеальный план)",38232,null],[38236,"2026-06-11T14:34:49",31,"//тогда ждем открытия окна",36440,null],[38237,"2026-06-11T14:35:36",10,"*использую Незримая поступь. Бонусным действием вы можете магически стать невидимыми до начала вашего следующего хода или пока вы не атакуете, не бросите кость урона, или не заставите кого-то совершить  и осматриваюсь в столовой*",36440,null],[38238,"2026-06-11T14:35:39",11,"— Я пожалуй подожду пока вы подадите мне верёвку сверху — Иштар осматривал окрестности опасаясь что кто-то заметит их на крыше",36440,null],[38239,"2026-06-11T14:35:52",9,"*Лёг на крышу, лежит глядя на звёзды. Протягивает руку к ним, любуется, он так давно их не видел.*",36440,null],[38240,"2026-06-11T14:36:03",5,"Рури оказывается в просторной столовой. На столах пусто, но в буфете около стены стоит куча чистой посуды. Серебряная, золотая, с инкрустрацией. Такая стоит дорого.",36440,null],[38241,"2026-06-11T14:36:24",9,"//Нага полез????",36440,null],[38242,"2026-06-11T14:36:26",31,"//мы не проникли, ждем откртыия окна",38240,null],[38243,"2026-06-11T14:36:34",11,"// только Рури внутри да",36440,null],[38244,"2026-06-11T14:36:38",10,"//Рури ток пролез и тот невидимый",36440,null],[38245,"2026-06-11T14:36:52",5,"Рури стоит в столовой. Вокруг никого.",36440,null],[38246,"2026-06-11T14:36:59",5,".",38240,null],[38247,"2026-06-11T14:37:09",11,"// щас он заберёт все что не приколочено и пойдет дальше",36440,null],[38248,"2026-06-11T14:37:34",10,"*акуратно прикладываю ухо к двери и если никого не слышу выхожу и тихо иду до лесницы*",36440,null],[38250,"2026-06-11T14:37:45",9,"*Леда вздохнул и пошёл осторожно помогать кентавру подняться на крышу, если тот не против/желает это сделать.*",36440,null],[38251,"2026-06-11T14:37:47",5,"// не так быстро",38248,null],[38252,"2026-06-11T14:38:10",10,"//шо кинуть ? скрытность? меня технически слышно но не видно",36440,null],[38253,"2026-06-11T14:38:17",11,"— Извини, приятель, карабкаться не моя сильная сторона — ему было стыдно быть обузой",38250,null],[38254,"2026-06-11T14:38:47",5,"Рури открывает дверь столовой. В кухне дальше по коридору шумит кухарка. Свободен путь направо и налево.",36440,null],[38255,"2026-06-11T14:38:56",31,"//могу свесить хвост, цепляйся за него, упирайся копытами в стену и залезай//",38253,null],[38256,"2026-06-11T14:39:01",5,"// вы ждёте на крыше первого этажа?",38250,null],[38257,"2026-06-11T14:39:26",10,"*смотрю в путь налево вижу кого?*",36440,null],[38258,"2026-06-11T14:39:34",10,"*типа по длине коридора*",36440,null],[38259,"2026-06-11T14:39:35",9,"— Силён, неуклюж. — *Кажется Леда о себе.* — Недостатки нам присущи.",38253,null],[38260,"2026-06-11T14:39:35",11,"// я полагаю на третий лезем",38256,null],[38261,"2026-06-11T14:39:44",9,"//На третий",38256,null],[38262,"2026-06-11T14:40:06",11,"Киваю и принимаю помощь от товарищей",38259,null],[38263,"2026-06-11T14:40:16",5,"Ты видишь стражника, стоящего к тебе спиной. Он закрывает весь проход своим телом.",38257,null],[38264,"2026-06-11T14:40:28",9,"//У меня ловкость 8, чтобы вы понимали)))",36440,null],[38265,"2026-06-11T14:40:41",11,"// у меня лучше, но я конь..",38264,null],[38266,"2026-06-11T14:40:48",10,"*окей обираю голову изза угла и смотрю в правый коридор*",36440,null],[38267,"2026-06-11T14:41:18",9,"//Мой чисто силой вытаскивает, через атлетику и расовой черты переносить грузы огромные)",38265,null],[38268,"2026-06-11T14:41:22",31,"у меня 16//",38264,null],[38269,"2026-06-11T14:41:41",11,"// самый гибкий толстячок тут",38268,null],[38270,"2026-06-11T14:41:47",5,"Вы залезли на крышу пока второго этажа.  Через окно видно, что комната  весьма богатая, висит куча картин и стоят какие-то золотые бюсты. Они бы отлично продались на черном рынке.",38262,null],[38271,"2026-06-11T14:42:06",31,"//жир смазывает кости))",38269,null],[38272,"2026-06-11T14:42:10",11,"// так и манишь, но мой персонаж не поведется",36440,null],[38273,"2026-06-11T14:42:33",5,"Справа пустой коридор. Вроде никого нет.",38266,null],[38274,"2026-06-11T14:42:35",9,"//Тоесть мы видим что на 3м этаже в окна раз на крыше второго?",38270,null],[38275,"2026-06-11T14:43:10",5,"// вы видите эту комнату на 2-м",36440,null],[38276,"2026-06-11T14:43:13",10,"*Иду тихонько босиком чтобы не издавать шума до поворота*",36440,null],[38277,"2026-06-11T14:43:36",5,"На повороте прямо в тебя шагает уборщица.",36440,null],[38278,"2026-06-11T14:43:44",5,"// кидай спас ловкости сл 13",36440,null],[38279,"2026-06-11T14:44:14",10,"/r 1d20+2",36440,null],[38281,"2026-06-11T14:44:32",31,"//пиздюли шваброй через 3,2,1...",38280,null],[38283,"2026-06-11T14:45:30",5,"Происходит столкновение, уборщица падает на пол и в шоке смотрит на тебя. Невидимость спадает.\n\n— Что за поганец, что это ты тут шляешься?",38280,null],[38284,"2026-06-11T14:46:17",10,"-Тише тише *говорю шепотом* я тут тайный страж. хожу в невидимости и слежу чтобы никто не воровал",36440,null],[38285,"2026-06-11T14:46:25",11,"// やれ やれ",36440,null],[38286,"2026-06-11T14:46:45",5,"// очень убедительно... кидай убеждение сл 17",38284,null],[38287,"2026-06-11T14:46:46",10,"-ты мне помешала бабуль... я не знаю что теперь будем говорить хозяину",36440,null],[38288,"2026-06-11T14:47:08",11,"// а что мы делаем ребят, кто-то из вас хочет залезть по воровать? Мой перс бы полез дальше на 3",36440,null],[38289,"2026-06-11T14:47:14",10,"//можно преимущество за то что бабка боится реакции хозяина?",36440,null],[38290,"2026-06-11T14:47:27",5,"// нет, ты несёшь какую-то дичь...",36440,null],[38291,"2026-06-11T14:47:34",10,"/r 1d20+6",36440,null],[38293,"2026-06-11T14:47:41",10,"//саси получаеца...",36440,null],[38294,"2026-06-11T14:47:48",11,"// может и дичь, но бабуля поверит",36440,null],[38295,"2026-06-11T14:48:04",11,"// Инсайд умеет убеждать людей я смотрю",36440,null],[38296,"2026-06-11T14:49:03",11,"— Леда, Орочи — Тихо окликивая товарищей кентавр указывает на крышу третьего этажа — продолжаем?",36440,null],[38297,"2026-06-11T14:49:13",31,"идем",38296,null],[38298,"2026-06-11T14:49:13",5,"— Ох, тайный страж! Не знала о таких делах. внучок. Иди тогда, охраняй.\n\nТы понимаешь, что уборщица тебе верит. Но вскоре она кому-нибудь обязательно расскажет о таком происшествии.",38292,null],[38299,"2026-06-11T14:49:44",5,"// кидай акробатике сл 10",38296,null],[38300,"2026-06-11T14:50:08",31,"всем троим?//",38299,null],[38301,"2026-06-11T14:50:09",10,"-Бабуль не усложняй нам двоим жизнь... Представь если ты кому то расскажешь то я больше не тайный страж получается. А ты нарушила планы хозяина. Так что это наш маленький секрет хорошо?",38298,null],[38302,"2026-06-11T14:50:14",5,"// кто первый лезет",38300,null],[38303,"2026-06-11T14:50:29",11,"// давайте самый атлетичный, я жду руки/веревки",36440,null],[38304,"2026-06-11T14:50:32",31,"тогда лучше я//",38302,null],[38306,"2026-06-11T14:50:48",31,"/r +5",38302,null],[38308,"2026-06-11T14:51:06",5,"— Ох, никому не расскажу, обещаю.\n\nТы понимаешь, что она обязательно расскажет.",38301,null],[38309,"2026-06-11T14:51:12",11,"— Ты прямо таки юркий, змей",36440,null],[38310,"2026-06-11T14:51:41",31,"*согласное шипение*",38309,null],[38311,"2026-06-11T14:51:42",10,"//... кибербабулинг",38308,null],[38312,"2026-06-11T14:52:09",9,"*Подаёт верёвку, чтобы его подтянул змей и подтолкнул кентавр знизу. А потом вместе затащим лошадь.*",36440,null],[38314,"2026-06-11T14:52:53",10,"-Бабуль а есть одежда служанки лишняя? пойдем вместе посмотрим есть ли ктото еще? Скажешь если что что я новый слуга",38308,null],[38315,"2026-06-11T14:53:06",10,"-Ты ведь мою невидимость нарушила",36440,null],[38316,"2026-06-11T14:53:35",5,"Змей встаёт на хвосте и заползает на крышу. Через окно видно служанку, подметающую в комнате. Охранник стоит у двери и ждёт, пока та закончит. Очевидно, кабинет под охраной.\n\nКрасивый меч с изумрудом на эфесе висит на стойке у стены.",38307,null],[38317,"2026-06-11T14:53:35",10,"-хозяин придет нас обоих уволят * почти плачу*",36440,null],[38318,"2026-06-11T14:54:23",5,"// кидай обман сл 17",38314,null],[38319,"2026-06-11T14:54:27",11,"— Спасибо, ребята, наконец-то третий этаж, осталось подождать пока Рури откроет окно изнутри.. надеюсь с ним там все в порядке — забравшись на крышу Иштар садится у стены что бы не привлекать внимание своей фигурой на крыше",38312,null],[38320,"2026-06-11T14:54:32",5,"// или убеждение",38317,null],[38321,"2026-06-11T14:54:38",10,"/r 1d20+6",36440,null],[38323,"2026-06-11T14:54:56",10,"//откуда такие сложности блин и непробиваемая бабка",36440,null],[38324,"2026-06-11T14:55:03",9,"*Леда припал к стене меж окнами, ждёт.*",36440,null],[38325,"2026-06-11T14:55:18",11,"// он нам не даёт много времени, не трать его зря и пробирайся дальше давай",36440,null],[38326,"2026-06-11T14:55:26",31,"указываю товаришам на то что увидел. будем ждать пока удет служанка а потом через окно пойдем за мечом?",38316,null],[38327,"2026-06-11T14:55:29",5,"— А, отстань от меня. Сбиваешь меня тут с ног, одежду просишь, работать мешаешь. Иди-ка отсюда, делай свою работу.",38314,null],[38328,"2026-06-11T14:55:49",11,"Иштар смотрит вниз с крыши интересуясь как идёт званный вечер хозяина поместья \n// Что мы там видим?",36440,null],[38329,"2026-06-11T14:56:03",10,"//хард а какой яд на моих столовых приборах раз убил короля?",36440,null],[38330,"2026-06-11T14:56:15",5,"Вы видите что все окна  закрыты.",38326,null],[38331,"2026-06-11T14:56:45",11,"— Ну меч на месте, шуметь не охота. Да и наш товарищ все ещё внутри.. предупредить бы его как-то о этих двоих",38316,null],[38332,"2026-06-11T14:56:47",31,"могу порробовать разбить, ловкостью чтобы бесшумно вышло//",38330,null],[38333,"2026-06-11T14:56:55",10,"*когда бабка отворачивается я (ей сворачиваю шею) использую заклинание сон *",36440,null],[38334,"2026-06-11T14:57:08",11,"// если провалишь мы нашумим",38332,null],[38335,"2026-06-11T14:57:09",9,"//Ты их превращал в полноценный артефакт? Если нет то самый простой и ток если провалит кто ещё и отравлен.",38329,null],[38336,"2026-06-11T14:57:19",5,"В соседнем особняке, ещё большем, чем этот, во всю идёт приём. Слышна веселая музыка, нарядные гости выходят из карет и заходят внутрь.\n\nНа втором этаже хозяин чем-то хвастается перед толпой гостей.",38328,null],[38337,"2026-06-11T14:57:25",10,"//какой то слабый король был)",38335,null],[38338,"2026-06-11T14:57:52",5,"// бесшумно разбить окно? это как?",38332,null],[38339,"2026-06-11T14:57:53",11,"— Да им пока что точно нет до нас дела..",38336,null],[38340,"2026-06-11T14:57:54",9,"//Артефакт сейчас по сути безделушка, её пробудить надо или тип того.",38337,null],[38341,"2026-06-11T14:58:49",31,"облепить стекло бумагой или тряпкой и стукнуть осторожно, чтобы сколки не звенели а упали в тряпку//",38338,null],[38342,"2026-06-11T14:58:53",9,"//Он даже не сработает щас, если дм не разрешит. Ведь не считается маг предметом :)",36440,null],[38343,"2026-06-11T14:59:41",11,"// я не верю в успех Рури честно говоря))",36440,null],[38344,"2026-06-11T14:59:54",5,"// щас, отойду на 5 минут",36440,null],[38345,"2026-06-11T15:00:29",10,"// та бабка эта страшнее чем все стражники )",36440,null],[38346,"2026-06-11T15:01:02",10,"//я щас её усыплю а это ваще не обыватель а король демонов со 100 хп",36440,null],[38347,"2026-06-11T15:01:32",9,"// а вдруг эта та самая Йотилла или её сестра)))",38346,null],[38348,"2026-06-11T15:01:58",10,"/у меня есть ниточка которая к ней приведет) так что не она",36440,null],[38349,"2026-06-11T15:01:59",11,"// чисто теоретически можем сломать окно и быстро забрать меч, а всю шумиху оставить на Рури..",36440,null],[38350,"2026-06-11T15:02:09",10,"//меч на приеме",36440,null],[38351,"2026-06-11T15:02:26",10,"//надо отсюда все вытащить что не приколочено",36440,null],[38352,"2026-06-11T15:02:37",9,"//Вот ток зашумят — оперативно ворвёмся",36440,null],[38353,"2026-06-11T15:02:38",11,".",38316,null],[38354,"2026-06-11T15:02:45",11,"// меч тут",36440,null],[38356,"2026-06-11T15:04:07",10,"//мне кстати ваще норм) вы тут все умрете даже если я выживу",36440,null],[38357,"2026-06-11T15:04:20",11,"Иштар осторожно заглядывает в окно что бы осмотреть меч",36440,null],[38368,"2026-06-11T15:06:39",5,"// я тут",36440,null],[38371,"2026-06-11T15:06:57",10,"а то улетело.",38333,null],[38372,"2026-06-11T15:07:03",5,"// ну как просто яд можно использовать",38342,null],[38374,"2026-06-11T15:08:08",11,"/roll d20+2",36440,null],[38375,"2026-06-11T15:08:09",5,"Заклинание срабатывает, бабка лежит на полу прямо посреди прохода и спит.",38333,null],[38377,"2026-06-11T15:09:04",10,"*оттаскиваю в уголок где можно было бы удобно прилечь и не видно с первого взгляда и оставляю бабку там. Иду в сторону лесницы*",38375,null],[38378,"2026-06-11T15:09:06",5,"Меч выглядит точь-в-точь как описал Карс. Руны на лезвии, изумруд на эфесе. Снять его со стойки у стены не будет проблемой.",38357,null],[38379,"2026-06-11T15:09:24",31,"//не воспользуйся ее положением, ты тут за другим,,,\\\\",38375,null],[38381,"2026-06-11T15:10:22",11,"// да он быстро справится не переживай))",38379,null],[38382,"2026-06-11T15:10:58",5,"Ты у лестницы. Охранник в коридоре слева прислонился и смотрит в стену. Рядом есть в ход в подвал. На стене висит Декоративный золотой кинжал.",38377,null],[38383,"2026-06-11T15:11:40",10,"*кинжал могу снять беспалевно? *",36440,null],[38384,"2026-06-11T15:11:58",10,"*обнаружение магии *",36440,null],[38385,"2026-06-11T15:12:02",5,"На третьем этаже все ещё идет уборка. Однако со второго не доносится ни звука.",36440,null],[38386,"2026-06-11T15:12:21",9,"//А невидимость не на концентрации тоже?)",36440,null],[38387,"2026-06-11T15:12:34",10,"//я уже видимый и нет не на концентрации",38386,null],[38388,"2026-06-11T15:12:43",10,"//это фича филборгов",36440,null],[38389,"2026-06-11T15:12:47",5,"Обычная декорация, сделанная из золота. Никакой магии, никакой практической ценности. Зато высокая цена.",38384,null],[38390,"2026-06-11T15:12:51",11,"Иштар периодически осторожно заглядывает внутрь комнаты что бы проверить не ушли ли стражник с горничной",36440,null],[38391,"2026-06-11T15:13:06",10,"*беру кинжальчик * // стражник увидит если я пройду до лесницы?",36440,null],[38392,"2026-06-11T15:13:47",5,"// нет, смотрит в сторону",38391,null],[38393,"2026-06-11T15:13:48",9,"//Как фирболг ты вродь можешь становится невидимым равное бм раз",36440,null],[38394,"2026-06-11T15:14:14",10,"//окак я это пропустил... Ставлюсь невидимым и иду по ступенькам на второй этаж",36440,null],[38395,"2026-06-11T15:14:37",5,"Уборка заканчивается, служанка готовится уходить. Вы понимаете, что стражник осмотрит комнату и, возможно, выглянет в окно, прежде чем уйти.",38390,null],[38396,"2026-06-11T15:15:11",31,"лезем на крыша нд окном",38395,null],[38397,"2026-06-11T15:15:23",31,"он же явно не будет откорывать окно и крутить головой",36440,null],[38398,"2026-06-11T15:15:39",5,"// на крышу 3-го этажа?",38396,null],[38399,"2026-06-11T15:16:01",31,"ну да//",38398,null],[38400,"2026-06-11T15:16:25",9,"Незримая поступь. Бонусным действием вы можете магически стать невидимым до начала вашего следующего хода или пока вы не атакуете, не бросите кость урона или не заставите кого-то совершить спасбросок. Вы можете использовать эту особенность количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования по окончании продолжительного отдыха.\n\n//Хотя хз если у тебя не из морденкаинена фирболг, а из книги игрока то так:\n\nНезримая поступь. Бонусным действием вы можете магически стать невидимыми до начала вашего следующего хода или пока вы не атакуете, не бросите кость урона, или не заставите кого-то совершить спасбросок.\n\nИспользовав эту особенность, вы не можете использовать её снова, пока не завершите короткий или продолжительный отдых.\n//У тебя какой фирболг?",36440,null],[38401,"2026-06-11T15:17:30",10,"//... из мордекайнена айнененана",36440,null],[38402,"2026-06-11T15:17:45",11,"// вообще можно и на второй спуститься временно",36440,null],[38403,"2026-06-11T15:17:54",5,"Ты находишься на втором этаже. На небольшом столике рядом с лестницей лежит красивое кольцо.\n\nСтражник стоит у стены и смотрит прямо на тебя. Ты вздрагиваешь и стараешься не сделать ничего глупого.\n\n// кидай спас мудрости сл 10",38394,null],[38408,"2026-06-11T15:18:22",10,"/r 1d20+2",38403,null],[38410,"2026-06-11T15:18:23",5,"// лезущие на крышу кидают акробатику сл 7",38399,null],[38411,"2026-06-11T15:18:36",5,"// кто спускается на 2-й спустились",36440,null],[38412,"2026-06-11T15:18:44",31,"/r +5",38410,null],[38414,"2026-06-11T15:18:56",9,"//Зачем... а перс что делает???",38402,null],[38415,"2026-06-11T15:19:19",5,"Ты стоишь на месте. Стражник смотрит сквозь тебя. Кольцо блестит на столе.",38409,null],[38416,"2026-06-11T15:19:21",11,"// просто как вариант, но окей давайте все на 3",38414,null],[38417,"2026-06-11T15:19:57",31,"8забрался на крышу третеьго этажа, наблюдаю за окном сверху. если охранник его откроет могу неожиданно на него напасть сверху и придушить*",36440,null],[38418,"2026-06-11T15:20:10",9,"//Сами решайте, я тут перед окнами 3го останусь. Если что договаривайтесь с Ледой вместе со мной",36440,null],[38419,"2026-06-11T15:20:25",11,"— Последуем за Орочи?",36440,null],[38420,"2026-06-11T15:20:38",11,"Смотрю на змея наверху и обращаюсь к Леде",36440,null],[38421,"2026-06-11T15:21:06",10,"*Не дыша иду на носочках в сторону от стража чтоб меня этот черт не видел *",38415,null],[38422,"2026-06-11T15:21:16",9,"*Непонимающе смотрит на тебя, он вообще не знает почему вы рискуете быть увиденными лазя по крыше перед окном туда сюда.*\n\n— Буду тут.",38419,null],[38424,"2026-06-11T15:21:45",5,"// ты на крыше рядом с окном, стражник скоро выглянет",38422,null],[38425,"2026-06-11T15:21:46",31,"если охранник выглянет из окна, он тебя заметит",38422,null],[38426,"2026-06-11T15:22:14",9,"//Я меж окнами лег, чтобы не посмотрел. Писал ранее",38424,null],[38427,"2026-06-11T15:22:15",11,"— Орочи, помоги взобраться",36440,null],[38428,"2026-06-11T15:22:29",31,"проятгиваю хвост",38427,null],[38429,"2026-06-11T15:23:05",11,"*Забираюсь к змею наверх и неловко стою на крыше стараясь не смотреть вниз*",36440,null],[38430,"2026-06-11T15:23:08",9,"//Я одного не пойму, мы перед окнами 2го или 3го этажа? Вродь же перед мечом на 3м писали",36440,null],[38431,"2026-06-11T15:23:26",11,"// мы перед нужным окном третьего этажа",38430,null],[38432,"2026-06-11T15:23:31",31,"//мы около окна третьего этажа, ты под ним, мы сверху",38430,null],[38433,"2026-06-11T15:23:56",31,"ждем что хранник свалит или открет окно и сможем напасть//",36440,null],[38434,"2026-06-11T15:23:57",9,"//Типа я сижу рядом с нужной вещью, не грабить сюда приполз",36440,null],[38435,"2026-06-11T15:24:03",5,"Рури успешно отходит из поля зрения стража. На этаже тихо, как будто больше никого нет.\n\nГордый воитель на картине на стене осуждающе смотрит на фембоя.",36440,null],[38436,"2026-06-11T15:24:09",5,"// да, 3",38430,null],[38437,"2026-06-11T15:24:21",10,"//обнаружение магии чтото говорит?",38435,null],[38438,"2026-06-11T15:24:35",5,"// кидай акробатику сл 7 с преимуществом",38429,null],[38439,"2026-06-11T15:24:44",5,"// обнаружение на что?",38437,null],[38442,"2026-06-11T15:25:08",10,"// магические ауры, какие школы магии действуют",36440,null],[38443,"2026-06-11T15:25:16",11,"/roll 20+2",36440,null],[38444,"2026-06-11T15:25:25",11,"// да..",36440,null],[38445,"2026-06-11T15:25:54",5,"От кольца на столе исходит слабая аура школы очарования. Больше ничего.",38437,null],[38447,"2026-06-11T15:26:21",9,"//Щас кинь",36440,null],[38448,"2026-06-11T15:27:00",9,"//Временно заменю бота, потом попробуем вернуть более удобного",36440,null],[38449,"2026-06-11T15:27:01",31,"//отойду на 10 минут",36440,null],[38451,"2026-06-11T15:27:29",10,"//насколько далеко кольцо от поворота в котором я?",36440,null],[38452,"2026-06-11T15:27:42",11,"/roll d20+2",36440,null],[38454,"2026-06-11T15:28:01",5,"Кольцо прямо на столе рядом с тобой.",38451,null],[38455,"2026-06-11T15:28:26",10,"*накрываю его ладонью и забираю... когда я накрываю его ладонью оно тоже становится невидимым*",36440,null],[38456,"2026-06-11T15:28:46",5,"Кентавр и нага залезли на крышу и сидят там. Рядом маняще торчит дымоход.",38453,null],[38459,"2026-06-11T15:29:21",10,"//мы счастливы Винсент? что я вижу в коридоре ?",36440,null],[38462,"2026-06-11T15:29:36",11,"// Леша отошёл пока, как вернётся я с ним поболтаю на эту тему, пока веди Рури",38456,null],[38466,"2026-06-11T15:30:20",11,"— Эй, Леда — кентавр шепчет спутнику снизу — страж с служанкой ушли?",36440,null],[38468,"2026-06-11T15:31:09",9,"*Осторожно заглядывает в окно делая на его краю малую иллюзию чтобы не видно было лица его изнутри. Чисто тёмное окно в уголке.*",36440,null],[38469,"2026-06-11T15:31:51",5,"Впереди лестница, в коридоре справа стоит охранник.\n\nВ комнате сзади тебя на постаменте стоит большой серебряный кубок.\n\nТы слышишь какое-то скрежетание, как будто кто-то лазает по крыше.",38459,null],[38470,"2026-06-11T15:32:05",10,"//магия?",36440,null],[38471,"2026-06-11T15:32:11",10,"//есть какая ?",36440,null],[38472,"2026-06-11T15:32:30",5,"// у тебя постоянный локатор?",36440,null],[38473,"2026-06-11T15:32:44",9,"//Концентрация до 10 минут вродь",36440,null],[38474,"2026-06-11T15:32:47",10,"//10 минут длится эта хуйня на обнаружение",36440,null],[38475,"2026-06-11T15:33:57",31,"//вернулся",36440,null],[38476,"2026-06-11T15:34:31",9,"//Окно там где меч, меня попросили взглянуть",38468,null],[38477,"2026-06-11T15:34:38",11,"— Орочи, смотри, здесь есть дымоход — указываю на него, а затем обращаюсь к Леде — в кабинете есть камин? Нужно понять куда он ведёт",36440,null],[38478,"2026-06-11T15:34:54",11,"// да, Эл, что там Леда видит?",36440,null],[38479,"2026-06-11T15:35:15",31,"*оцениваю дымоход. пожалуй, пролезу*",36440,null],[38480,"2026-06-11T15:35:32",11,"// главное что бы он не вел на первый этаж, а то устроит нам тут ловушку джокера Эл)",36440,null],[38481,"2026-06-11T15:35:34",5,"Рядом магии нет, кроме кольца в руке. Ты понимаешь, что оно делает (частично)\n\nЭто кольцо имеет 6 зарядов. Пока вы носите его, вы можете потратить 1 из его зарядов, чтобы в течение 1 минуты ваш голос был четко слышен всем существам в радиусе 1 мили от вас, независимо от постороннего шума. Магическая тишина, 1 фут камня, 1 дюйм обычного металла, тонкий лист свинца или 3 фута дерева блокируют эту проекцию.",38471,null],[38482,"2026-06-11T15:36:07",5,"// окей, сорри",38468,null],[38483,"2026-06-11T15:36:47",10,"*Осматриваю кубок на предмет ловушек под ним*",36440,null],[38484,"2026-06-11T15:36:55",5,"Ты видишь стражника, смотрящего в соседнее окно. Он  не видит ничего подозрительного, встаёт и выходит из комнаты.",38468,null],[38485,"2026-06-11T15:37:32",5,"Дымоход как будто короткий, через него слышны шаги стражника в комнате.",38479,null],[38486,"2026-06-11T15:37:52",31,"хочу залезть в него. что то бросать?//",38485,null],[38487,"2026-06-11T15:38:02",5,"Удивительно, но в доме всё ещё нет никаких ловушек. Кубок можно забирать.",38483,null],[38488,"2026-06-11T15:38:08",5,"// себя",38486,null],[38489,"2026-06-11T15:38:13",11,"— Ты у нас самый юркий — Иштар обращается к наге — сможешь бесшумно пролезть?",36440,null],[38490,"2026-06-11T15:38:22",31,"*ныряю в дымоход*",38488,null],[38491,"2026-06-11T15:38:23",5,"// опиши как ты лезешь по трубе",36440,null],[38492,"2026-06-11T15:38:27",10,"*беру кубок тогда... Есть еще чтото в комнате интересное ?",36440,null],[38493,"2026-06-11T15:38:38",9,"*Шепчу но малой иллюзией создаю свой голос поближе к союзникам.*\n\n— Страж отошёл.",36440,null],[38494,"2026-06-11T15:39:13",11,"Иштар присвистывает смотря как змей проскользнул в дымоход \n— Действительно шустрый \"малый\" — тихо озвучил он свои мысли",36440,null],[38495,"2026-06-11T15:39:16",5,"Дверь в следующую комнату. Как ты вспоминаешь, Оттуда можно выйти на крышу через окну.",38492,null],[38496,"2026-06-11T15:39:33",31,"просовая для начала голову, вытягиваю тело, стараясь его сузить, на манер червяка, помога. себе руками и телом. ползу по трубе пока не попадпю в камин. надеюсь. он не горит?)",38491,null],[38497,"2026-06-11T15:39:59",10,"*Иду туда и осматриваю комнату *",38495,null],[38498,"2026-06-11T15:40:31",5,"Змей оказывается в камине весь в саже. Прямо около его лица пятки стражника.",36440,null],[38499,"2026-06-11T15:40:50",5,"В комнате немало всяких украшений и ожерелий. Окна легко открываются.",38497,null],[38500,"2026-06-11T15:40:51",31,"он выходит из комнаты или очит на месте?//",38498,null],[38501,"2026-06-11T15:41:26",5,"Охранник топчется на месте, и не думая никуда уходить.",38500,null],[38502,"2026-06-11T15:41:28",10,"*если нет магии я хватаю все что могу*",38499,null],[38503,"2026-06-11T15:41:52",31,"могу напасть и скрутить, премимущестов на атаку есть?//",38501,null],[38504,"2026-06-11T15:41:56",5,"// прям хватаешь? кидай ловкость рук сл 14",38502,null],[38505,"2026-06-11T15:42:08",5,"// преимущество есть",38503,null],[38506,"2026-06-11T15:42:17",9,"//Я так понял что прямо перед нужным окном где видно меч?",36440,null],[38507,"2026-06-11T15:42:22",5,"// да",38506,null],[38508,"2026-06-11T15:42:25",31,"да//",38506,null],[38509,"2026-06-11T15:42:48",10,"//погодите я с локатором магии иду уже почти тас",36440,null],[38510,"2026-06-11T15:43:00",5,"// кидай)",38504,null],[38511,"2026-06-11T15:43:17",31,"/r +d20 +3",36440,null],[38513,"2026-06-11T15:43:22",11,"// кусай его за пятку",36440,null],[38514,"2026-06-11T15:43:29",9,"*Леда так как ушёл стражник оценивает растояние к мечу и не закрыто ли хоть одно из окон. А вдруг, чтобы не шуметь.*",36440,null],[38515,"2026-06-11T15:43:42",31,"/r +3",36440,null],[38517,"2026-06-11T15:43:47",5,"Все окна закрыты, как и дверь",38514,null],[38518,"2026-06-11T15:44:21",5,"Стражник оказался в объятьях наги. Вы катитесь по полу в обнимку.",38512,null],[38519,"2026-06-11T15:44:27",31,"нападаю и бью телом, стремлюсь его опутать, особенно целюсь в шею, чтоюбы не поднял шума",38512,null],[38520,"2026-06-11T15:44:40",31,"/roll 1d6+3",36440,null],[38522,"2026-06-11T15:44:46",9,"*Вздыхает, думает стоит ли...*",36440,null],[38523,"2026-06-11T15:45:04",11,"Подаю руку Леде\n— Лезь если хочешь за ним",36440,null],[38524,"2026-06-11T15:45:16",31,"стражник опутан, СЛ 13 на силу чтобы выбрстся//",36440,null],[38525,"2026-06-11T15:45:26",5,"// это урон?",38521,null],[38526,"2026-06-11T15:45:30",31,"да",38525,null],[38527,"2026-06-11T15:45:44",5,"/roll d20+3",38524,null],[38529,"2026-06-11T15:46:17",31,"продолжать бить?//",36440,null],[38530,"2026-06-11T15:46:27",11,"// может он его просто вырубить?",36440,null],[38531,"2026-06-11T15:46:36",5,"// ты будешь кидать?",38509,null],[38532,"2026-06-11T15:46:46",9,"— Мечь вот, протянуть руку, взять. — *Тихо говорил Леда.* — Подставить своих.",38523,null],[38533,"2026-06-11T15:46:48",31,"//я и планировал нелетально бить//",38530,null],[38534,"2026-06-11T15:47:21",10,"*слышу грохот тел сверху и иду в сторону стражника который на втором этаже*",38531,null],[38535,"2026-06-11T15:47:31",11,"— Залезь к нему и открой окно, мы можем связать стражника",36440,null],[38536,"2026-06-11T15:47:35",5,"Стражник опутан, он немного ослаб и бьётся, пытаясь высвободиться. Удар короткого меча проходит по чешуе наги.",38528,null],[38537,"2026-06-11T15:47:35",9,"//Так, мы слышим шум?)",36440,null],[38538,"2026-06-11T15:47:50",10,"Они по полу катаются же//",38537,null],[38539,"2026-06-11T15:47:52",5,"// слышите",38537,null],[38540,"2026-06-11T15:48:19",9,"*Леда слышит шум... и понимает что надо действовать, ведь его слышат скорее всего все.*",36440,null],[38541,"2026-06-11T15:48:38",5,"Ты идёшь в сторону лестницы, стражник идёт прямо к тебе.Он явно услышал, как ты сметал с полок все украшения.",38534,null],[38542,"2026-06-11T15:48:55",5,"/roll d20+5",36440,null],[38545,"2026-06-11T15:49:09",10,"*стою в углу и задерживаю дыхание*// скрытность?",36440,null],[38546,"2026-06-11T15:49:15",5,"// меч не наносит вреда наге",38543,null],[38547,"2026-06-11T15:49:23",5,"// скрытность сл 10",38545,null],[38548,"2026-06-11T15:49:51",31,"/r +3\n/r +3",38546,null],[38549,"2026-06-11T15:49:52",10,"/roll d20+2",36440,null],[38552,"2026-06-11T15:50:10",10,"//за невидимость можно преимущество?",36440,null],[38553,"2026-06-11T15:50:19",9,"*Леда поднимает руки как могучий гигант, входит в ярость сжимая пику в руках. С разбегу, в ярости всем весом толкает окно чтобы оно вылетело вместе со створкой и это ещё и удар великана!*",36440,null],[38555,"2026-06-11T15:50:32",10,"/roll d20+2",36440,null],[38557,"2026-06-11T15:50:40",5,"// это что?",38550,null],[38558,"2026-06-11T15:50:42",9,"//Ярость+удар великана это с разбега ещё всем весом просто нахуй окно я думаю",36440,null],[38559,"2026-06-11T15:51:10",31,"это я хотел удар нанести с преимущестовом, но что то бот не дает дважды бросить//",38557,null],[38560,"2026-06-11T15:51:27",5,"Окно вылетает с грохотом, осколки падают по всей комнате. Леда стоит внутри, меч совсем рядом. На других постаментах красуются ещё какие-то бюсты и кубки.",38553,null],[38561,"2026-06-11T15:51:34",10,"/roll 1d20+2",36440,null],[38563,"2026-06-11T15:51:51",10,"Хм...//",36440,null],[38564,"2026-06-11T15:52:08",5,"Стражник прошёл мимо, в ограбленную комнату.",38562,null],[38569,"2026-06-11T15:52:40",31,"*хриплю: Леда, помоги, выруби его (стражника)*",38560,null],[38571,"2026-06-11T15:53:10",9,"*Просто протягивает руку и берёт меч. Вы лазит с ним обратно, но раз зашумел... надо предупредить своих тоже...*\n\n— АааааааАААААААААААААААгггггрррррххххххххх!!! — *Закричал Леда чтобы слышали все и вся.*",38560,null],[38572,"2026-06-11T15:53:33",9,"//Мы же в разных местах вообще?",38569,null],[38573,"2026-06-11T15:53:46",5,"// в соседней комнате",38572,null],[38574,"2026-06-11T15:53:46",31,"нет// в одном//",38572,null],[38575,"2026-06-11T15:53:56",9,"//А ну раз так",38573,null],[38576,"2026-06-11T15:53:58",10,"* когда он прошел я иду в его коридор где он стоял и смотрю куда можно пройти *",38564,null],[38577,"2026-06-11T15:54:04",9,"//Откуда мне знать?",36440,null],[38578,"2026-06-11T15:54:16",9,"//Леда щнал что наг в соседней комнате?",36440,null],[38580,"2026-06-11T15:54:36",31,"//я думал что нырнул в кабинет и меня видят в окно//",36440,null],[38581,"2026-06-11T15:54:37",5,"// шум в соседней комнате",38578,null],[38582,"2026-06-11T15:55:02",5,"// нет, страж вышел из той комнаты и стоял  в этой окло лестницы.",38580,null],[38583,"2026-06-11T15:55:20",9,"*Идёт на помощь товарищу в первую очередь тогда.*",38571,null],[38584,"2026-06-11T15:55:24",11,"*Забираюсь вслед за Ледой и держу на готове верёвку*",36440,null],[38585,"2026-06-11T15:55:24",5,"Путь к лестнице свободен. Наверху явно что-то происходит",38576,null],[38586,"2026-06-11T15:55:26",31,"ну тогда я его сейчас отптзжу и уйду через окно//",36440,null],[38587,"2026-06-11T15:55:39",10,"* я ищу по новым комнатам сокровища *",38585,null],[38588,"2026-06-11T15:55:42",5,"Вы с нагой в комнате рядом с опутанным стражем.",38584,null],[38589,"2026-06-11T15:55:47",11,"— Нам всего лишь нужно заставить его заткнуться, не обязательно убивать",36440,null],[38590,"2026-06-11T15:56:07",31,"так дай ему копытом по башке пока я его держу",38589,null],[38591,"2026-06-11T15:56:14",9,"*Хватает стража и бросает в стену.*",38588,null],[38592,"2026-06-11T15:56:19",11,"// для этого что-то бросать надо?)",36440,null],[38593,"2026-06-11T15:56:29",9,"/roll 1d20+4 захват атлетика",36440,null],[38595,"2026-06-11T15:56:30",5,"// кидайтн атаки с преимуществом",36440,null],[38596,"2026-06-11T15:56:44",11,"// ахренеть вы не шумные..",36440,null],[38597,"2026-06-11T15:56:52",9,"/roll 1d20+4 захват атлетика преимущество тогда",36440,null],[38598,"2026-06-11T15:56:53",10,"//я стелс",36440,null],[38600,"2026-06-11T15:57:09",11,"Иштар понял что товарищи справятся сами и идёт за мечем",36440,null],[38601,"2026-06-11T15:57:15",9,"*Помогаю подняттся Нагу.*\n\n— Бежим. Пора.",36440,null],[38602,"2026-06-11T15:57:25",5,"Фембой игнорирует шум и заходит в ещё одну комнату. Там стоит бюст какого-то полководца, серебряный. Рури забирает его.",38587,null],[38603,"2026-06-11T15:57:26",9,"//Он у меня",38600,null],[38604,"2026-06-11T15:57:41",11,"// а сори",38603,null],[38605,"2026-06-11T15:57:51",10,"//есть ещё комнаты рядом ?) я бы зашел",38602,null],[38606,"2026-06-11T15:57:57",31,"//мародерим кабинет?//",36440,null],[38607,"2026-06-11T15:58:02",9,"*Леда настроен убегать, на добычу ему плевать.*",36440,null],[38608,"2026-06-11T15:58:06",11,"// ты добряк же был..",38606,null],[38609,"2026-06-11T15:58:24",31,"поэтому и не от лица персонажа спрашиваю//",38608,null],[38610,"2026-06-11T15:58:27",9,"//Надеюсь стража не прибил когда в стену бросил ~",36440,null],[38611,"2026-06-11T15:58:29",5,"// нету",38605,null],[38612,"2026-06-11T15:58:32",11,"— Уходим тем же путем? — указываю на разбитое окно — Мне кажется пора уйти пока нас не обнаружили, времени мало",38607,null],[38613,"2026-06-11T15:58:50",31,"да, валим через окно. Рури надеюсь выберется",38612,null],[38614,"2026-06-11T15:58:50",5,"Страж лежит у стены и смотрит на вас. Он пытается выровнять дыхание, чтобы встать.",38610,null],[38615,"2026-06-11T15:59:05",9,"— Да. — *Леда и так уже идёт через дыру в стене от окна.*",38612,null],[38616,"2026-06-11T15:59:08",11,"// бро выруби его пока он не умер",36440,null],[38617,"2026-06-11T15:59:18",5,"// из кабинета берёте только меч? кто первый выходит через окно?",36440,null],[38618,"2026-06-11T15:59:23",9,"— Заговоришь — умрёшь.",38614,null],[38619,"2026-06-11T15:59:27",11,"// только меч",38617,null],[38620,"2026-06-11T15:59:27",10,"*что вокруг меня в комнате ? Есть что-то поджечь ?*",38611,null],[38621,"2026-06-11T15:59:33",11,"Иштар выбирается первый",36440,null],[38622,"2026-06-11T15:59:43",5,"Всякие бумаги лежат на письменном столе.",38620,null],[38623,"2026-06-11T15:59:48",5,"Страж кивает",38618,null],[38624,"2026-06-11T16:00:02",10,"//если я прочитаю там будет что-то важное ?",38622,null],[38625,"2026-06-11T16:00:06",9,"*Вышел на крышу и спускается.*",36440,null],[38626,"2026-06-11T16:00:21",9,"*Помогаю остальным тоже.*",36440,null],[38627,"2026-06-11T16:00:23",5,"// там будет приглашение на казнь",38624,null],[38628,"2026-06-11T16:00:23",31,"*тоже сваливаю через окно и крышу*",36440,null],[38629,"2026-06-11T16:00:35",5,"Ваше вторжение не осталось не замеченным. Снизу летят 2 арбалетных болта.",38621,null],[38630,"2026-06-11T16:01:05",5,"/roll d20+4",36440,null],[38632,"2026-06-11T16:01:14",9,"//Можно реакцией сделать круто?",38629,null],[38633,"2026-06-11T16:01:16",5,"/roll d20+4",36440,null],[38635,"2026-06-11T16:01:23",5,"// давай",38632,null],[38636,"2026-06-11T16:01:40",9,"//Пох, все равно не попали, но все равно",36440,null],[38637,"2026-06-11T16:01:49",5,"// шучу, ничего особого",38624,null],[38638,"2026-06-11T16:03:12",10,"//ну беру приглашение... Использую на ткань , стол и остальные бумаги использую заговор фокус и развожу пожар. Как и в комнате с бюстом и выхожу в окно туманным шагом*",38627,null],[38639,"2026-06-11T16:03:14",9,"*Леда проводит рукой в воздухе и перед ним обращуется черное зеркало. Оно разюивается на осколки и два из них сбивают болты а третье попадает в одного из тех кто стрелял в них раня лицо. Щвук как битое стекло, чёрное, хруст. Предупреждение.*",36440,null],[38640,"2026-06-11T16:03:34",9,"/roll 1d20+2 запугивание для этого даж ячейку потратил в молоко",36440,null],[38642,"2026-06-11T16:03:53",5,"// давай с преимуществом",38641,null],[38643,"2026-06-11T16:04:05",9,"//Использовал магические стрелы для отыгрыша",36440,null],[38644,"2026-06-11T16:04:06",11,"— Хороший фокус, приятель — вы видите как кентавр спрыгивает с крыши, очевидно что спускаться ему проще чем подыматься — Орочи, валим в лес!",36440,null],[38645,"2026-06-11T16:04:14",9,"/roll 1d20+2 преимущество",36440,null],[38647,"2026-06-11T16:04:29",5,"//ты на окне 2-го этажа, соучастники прыгают по крышам вниз",38638,null],[38648,"2026-06-11T16:04:57",5,"Стражник снизу опускает арбалет. Другой стреляет прямо в Леду.",38646,null],[38649,"2026-06-11T16:04:57",10,"// я все поджигаю фокусом что вижу и прыгаю на землю туманным шагом",38647,null],[38650,"2026-06-11T16:05:09",5,"/roll d20+4",36440,null],[38654,"2026-06-11T16:05:32",10,"// не в замес а в кусты куда то где не видно",38649,null],[38656,"2026-06-11T16:05:54",5,"/roll d10+3",36440,null],[38658,"2026-06-11T16:06:03",5,"// 6 урона леде",38657,null],[38659,"2026-06-11T16:06:04",9,"/roll 1d12+3 выносливость камня на столько меньше урона получил",36440,null],[38661,"2026-06-11T16:06:38",5,"У особняка стоит телега, там сидит Карс и с восторгом смотрит за развитием событий.",36440,null],[38662,"2026-06-11T16:06:54",10,"//отмена операции я забираюсь на третий этаж",36440,null],[38663,"2026-06-11T16:07:20",9,"*Леда берёт камень из мешка и метает в противника пока слазит.*",36440,null],[38664,"2026-06-11T16:07:27",10,"//я чувствую что недостаточно поджог ...",36440,null],[38665,"2026-06-11T16:07:58",5,"Камень больно ударяет одного из охранников, но не останавливает его.",38663,null],[38666,"2026-06-11T16:08:04",5,"// вы спускаетесь?",36440,null],[38667,"2026-06-11T16:08:04",9,"*Стрела просто отскочила как от стены.*",38660,null],[38668,"2026-06-11T16:08:36",9,"//Тоесть я попал без броска?",38665,null],[38669,"2026-06-11T16:08:37",11,"// да",38666,null],[38670,"2026-06-11T16:08:46",9,"//Да, конечно",38666,null],[38671,"2026-06-11T16:08:56",5,"На 3 этаже тебе прямо в лицо прилетает болт из арбалета. Стражник стоит около раненого товарища.",38662,null],[38672,"2026-06-11T16:09:03",9,"//Тогда удар великана, спас силы сл 13 или он упал)",38668,null],[38673,"2026-06-11T16:09:06",5,"/roll d20+4",36440,null],[38675,"2026-06-11T16:09:11",10,"//я хочу подняться на третий этаж и в окно где был меч использовать заклинание огненные ладони... 15 футов огнем по конусу",38666,null],[38676,"2026-06-11T16:09:18",10,"//попал",38674,null],[38677,"2026-06-11T16:10:05",5,"Фембой вытягивает руки для заклинания, но тут в его ногу впивается болт. Он падает на спину на крышу второго этажа.",38675,null],[38678,"2026-06-11T16:10:18",5,"/r d10+3",36440,null],[38680,"2026-06-11T16:10:20",10,"//давайте сейчас по инициативе ходить ?",36440,null],[38681,"2026-06-11T16:10:31",5,"/roll d20+3",38672,null],[38683,"2026-06-11T16:10:34",9,"//Иню кидаем? Мы бежим! Решайте сами, я даж на урон не кидал и на попадание",36440,null],[38684,"2026-06-11T16:10:48",31,"так только ты в бою, мы вали//",38680,null],[38685,"2026-06-11T16:10:53",11,"// я вообще рывком в лес собралась уже да",36440,null],[38686,"2026-06-11T16:11:00",5,"Оба стражника внизу выведены из строя. Один напуган, другой лежит",38682,null],[38688,"2026-06-11T16:11:28",11,"— Хватит избивать невиновных людей, уходи — кричу великану",36440,null],[38689,"2026-06-11T16:11:31",10,"*всеравно забираюсь в окно и использую огненые ладони *",36440,null],[38690,"2026-06-11T16:11:42",9,"*Леда спускается, даже не так, он спрыгивает.*\n\n//Сколько высота?",36440,null],[38691,"2026-06-11T16:11:44",5,"// ещё один болт в лицо",38689,null],[38692,"2026-06-11T16:11:59",5,"/roll d20+4",36440,null],[38694,"2026-06-11T16:12:09",5,"/r d10+3",36440,null],[38696,"2026-06-11T16:12:18",10,"//это заебись конечно но можно по инициативе ходить раз я в бою?",36440,null],[38697,"2026-06-11T16:12:39",10,"//а то он и реакцию заготавливает и стреляет каждый ход не дохуя ?",36440,null],[38698,"2026-06-11T16:13:05",5,"// хмм, 30 футов?",38690,null],[38699,"2026-06-11T16:13:46",5,"// хм ладно",38696,null],[38700,"2026-06-11T16:13:48",10,"//даже до моих действий просто как из автомата хуярит",36440,null],[38701,"2026-06-11T16:13:56",5,"// тогда кидай акробатику 10 чтобы залезть",36440,null],[38702,"2026-06-11T16:14:09",10,"/roll 1d20+2",36440,null],[38704,"2026-06-11T16:14:35",5,"// действуй",36440,null],[38705,"2026-06-11T16:14:36",10,"действие ?\\\\",36440,null],[38706,"2026-06-11T16:14:47",5,"// остальные где-то у телеги я так понимаю",36440,null],[38707,"2026-06-11T16:14:50",10,"*огненные ладони в окно кабинета*",36440,null],[38708,"2026-06-11T16:15:07",11,"//ну по крайней мере мы с нагой",38706,null],[38709,"2026-06-11T16:15:08",10,"/roll 3d6+2",36440,null],[38711,"2026-06-11T16:15:33",5,"// опиши как кабинет загорелся",38707,null],[38712,"2026-06-11T16:15:41",9,"//Ну тогда на все, чё, просто в ярости скидываюсь",36440,null],[38713,"2026-06-11T16:15:41",9,"//Минус ещё ярость",36440,null],[38714,"2026-06-11T16:16:07",10,"*от волны огня из рук все что в кабинете начинает полыхать. Единорог в восторге как и Рури*",36440,null],[38715,"2026-06-11T16:16:57",5,"— Пожар! — заорали все стражники. Охранник на третьем этаже бросил арбалет и принялся вытаскивать раненого товарища. Внизу из двери выбегают служанки.",36440,null],[38716,"2026-06-11T16:17:02",10,"* на остаток движения я разбегаюсь в сторону обрыва и прыгаю в угол дома где нет никого и использую туманный шаг *",36440,null],[38717,"2026-06-11T16:17:14",9,"/roll 3d6 половина урона от падения",36440,null],[38719,"2026-06-11T16:17:25",10,"//туманный шаг это тп на 30 футов",36440,null],[38720,"2026-06-11T16:17:34",9,"/roll 1d12+3 выносливость камня вторая",36440,null],[38722,"2026-06-11T16:17:41",5,"// типа на крышу первого этажа?",38716,null],[38723,"2026-06-11T16:18:14",10,"//Типа прыгаю вниз и использую туманный шаг чтобы телепортироваться на землю",36440,null],[38724,"2026-06-11T16:18:41",9,"*Леда просто впечатался в землю и встал как ни в чём не бывало, просто пошёл к телеге.*\n\n//Все абилки и ярости потратил, зато 0 урона получил",36440,null],[38725,"2026-06-11T16:18:51",5,"Бабушка-уборщица, которую ты сбил с ног, узнаёт тебя.\n\n— Ах ты поганец! Да я тебя!\n\nОна кидает грязную тарелку.",36440,null],[38726,"2026-06-11T16:19:00",5,"/roll d20",36440,null],[38728,"2026-06-11T16:19:06",10,"//попала...",36440,null],[38729,"2026-06-11T16:19:08",5,"/roll d4",36440,null],[38731,"2026-06-11T16:19:30",5,"// живой?",38730,null],[38732,"2026-06-11T16:19:33",10,"//неа",36440,null],[38733,"2026-06-11T16:19:39",11,"// ХАХВХАХВХА",36440,null],[38734,"2026-06-11T16:20:02",11,"Завидев эту картину кентавр бросается к Рури //как я далеко от него?",36440,null],[38735,"2026-06-11T16:20:18",9,"//Жадность фраера сгубила. Там доки о его казни лежат похоже ~",36440,null],[38736,"2026-06-11T16:20:20",5,"Рури без сознания падает недалеко от телеги. Бабушка грозит кулаком.",36440,null],[38737,"2026-06-11T16:20:24",10,"🪬зато я все вынес и поджог\\\\",36440,null],[38738,"2026-06-11T16:20:25",5,"// 10 футов",38734,null],[38739,"2026-06-11T16:20:35",31,"//ну это точно в эпики",36440,null],[38740,"2026-06-11T16:20:40",11,"— Бабка, вали пожар тушить",36440,null],[38741,"2026-06-11T16:20:47",31,"//бабка-ниндзя блеать//",36440,null],[38742,"2026-06-11T16:20:51",11,"/roll d20+2",36440,null],[38744,"2026-06-11T16:20:55",11,"//да рофл",36440,null],[38745,"2026-06-11T16:21:02",11,"// запугивание было",36440,null],[38746,"2026-06-11T16:21:09",11,"— Орочи, прогони ее пожалуйста",36440,null],[38747,"2026-06-11T16:21:17",10,"//та хватай меня и бегии форест емана",36440,null],[38748,"2026-06-11T16:21:21",31,"//могу кинуть на медицину чтобы помочь?//",36440,null],[38749,"2026-06-11T16:21:22",11,"Достаю кисель и кормлю Рури",36440,null],[38750,"2026-06-11T16:21:49",5,"— Ну что вы? Залезайте и поехали. Пожар привлёк слишком много внимания.\n\nКарс торопит вас, сидя в телеге.",36440,null],[38751,"2026-06-11T16:22:01",9,"//Он не годится для... ну лан. Просто работает как чудо ягоды ~",38749,null],[38752,"2026-06-11T16:22:01",31,"/roll 1d20+2",38746,null],[38753,"2026-06-11T16:22:02",5,"// вот всё",38749,null],[38755,"2026-06-11T16:22:09",11,"// не надо ничего кидать, пускай Рури валит, я подняла",36440,null],[38756,"2026-06-11T16:22:24",10,"//все мы в телеге кароч)",36440,null],[38757,"2026-06-11T16:22:32",9,"*Садится на телегу и пьёт зелье уменьшение чтобы та его потащила.*",38750,null],[38758,"2026-06-11T16:23:04",5,"— Но! Но!\n\nЛошади стартуют бодро и телега укатывается прочь от горящего особняка.",36440,null],[38759,"2026-06-11T16:23:07",11,"*галопом следую за телегой*",36440,null],[38760,"2026-06-11T16:23:26",5,"Вскоре вы приезжаете к таверне и вновь оказываетесь в комнатушке со столом.",36440,null],[38761,"2026-06-11T16:24:55",5,"Карс стоит за столом, вы с другой стороны.\n\n— Вижу, меч у вас. Отличная работа! Правда, можно было обойтись без пожара...",36440,null],[38762,"2026-06-11T16:25:09",10,"-зато все на него отвлеклись",36440,null],[38763,"2026-06-11T16:25:18",10,"-я найду эту бабку...позжн",36440,null],[38764,"2026-06-11T16:25:32",31,"//смерти ищещшь?)",38763,null],[38765,"2026-06-11T16:25:33",9,"*Леда ни капли не пострадавший, слегка потрёпанный лишь.*\n\n— Пожар — не общее решение.",36440,null],[38766,"2026-06-11T16:25:34",5,"— Если кто-то погибнет в огне, стражи будут долго искать виновных. Но, что есть, то есть",36440,null],[38767,"2026-06-11T16:26:27",11,"— Мы вроде не трогали ничего — не понимая как это произошло ответил кентавр",38761,null],[38768,"2026-06-11T16:26:32",10,"-да не было там никого. Просто домик спалил чуть-чуть.*мило улыбается * - зато никто не узнает что мы украли",36440,null],[38769,"2026-06-11T16:27:03",11,"— Ты подпалил дом с живыми невиновными людьми?",38768,null],[38770,"2026-06-11T16:27:07",10,"-боюсь я все поджог *хлопаю кентавра* - но не бойся это план ! надежный!",38767,null],[38771,"2026-06-11T16:27:08",5,"Рюкзак Рури полон награбленных украшений. Внезапно он падает за землю и золотые побрякушки рассыпаются по грязному полу.",36440,null],[38772,"2026-06-11T16:27:29",10,"-Вот зато скок я нашел всего",36440,null],[38773,"2026-06-11T16:27:41",11,"*Со злостью убираю руку Рури*\n— Как ты мог?! А если кто-то невиновный умрет из-за этого?",38770,null],[38774,"2026-06-11T16:27:44",9,"*Качает головой.*\n\n— Жадность.",36440,null],[38775,"2026-06-11T16:27:46",5,"— Вижу, вы не стеснялись брать из дома всё ценное, — Карс пристально смотрит на Рури",36440,null],[38776,"2026-06-11T16:27:53",11,"Иштар презрительно смотрит на тебя и твою добычу",38772,null],[38777,"2026-06-11T16:27:56",10,"-да все выбежали все нормально",38773,null],[38778,"2026-06-11T16:28:06",11,"// ничего личного, перс порядочный",36440,null],[38779,"2026-06-11T16:28:07",10,"-Тьфу идите вы. Не хотите я себе заберу",36440,null],[38780,"2026-06-11T16:28:14",9,"*Просто очень осуждающе смотрит.*",36440,null],[38781,"2026-06-11T16:28:25",10,"-Вы вообще тоже воровали!",36440,null],[38782,"2026-06-11T16:28:34",10,"-просто я лучше)",36440,null],[38783,"2026-06-11T16:28:38",9,"*Леда берёт побрякушки и отдаёт нанимателю всё.*",36440,null],[38784,"2026-06-11T16:28:46",11,"— Мы вернули меч его владельцу, больше ничего и пальцем не тронули!",36440,null],[38785,"2026-06-11T16:29:04",31,"*согласно киваю*",38784,null],[38786,"2026-06-11T16:29:08",11,"Кажется Иштар начал жалеть о оказанной ранее помощи",36440,null],[38787,"2026-06-11T16:29:09",5,"— Ого! Нет, что вы. Мне нужен только меч. Остальное ваше, и зелья оставьте, что я вам дал.",38783,null],[38788,"2026-06-11T16:29:33",5,"— Кстати, у меня для вас есть немного свитков в подарок, может пригодятся.",36440,null],[38789,"2026-06-11T16:29:41",10,"- преступление даже во благо всеравно преступление *хихикаю* - ну ладно помоги продать это добро будь зайкой",36440,null],[38790,"2026-06-11T16:29:47",5,"— Спасибо! Я очень благодарен!",38784,null],[38791,"2026-06-11T16:30:02",9,"*Леда шёл помогать а не грабить, он немного расстроен.*",38787,null],[38792,"2026-06-11T16:30:11",11,"— Благодарю. — Иштар кивает",38787,null],[38793,"2026-06-11T16:31:15",5,"Карс берёт меч и с восторгом осматривает его.\n\n— Меч отца в моих руках... Даже не верится",36440,null],[38794,"2026-06-11T16:31:28",11,"Кентавр выглядел раздраженным и разочарованным. Он ни капли не заинтересован в добыче Рури, только в награде от заказчика",36440,null],[38795,"2026-06-11T16:31:44",10,"*даю приглашение на казнь * - тебе интересно ?",38790,null],[38796,"2026-06-11T16:32:33",5,"— Боюсь, я сам небогат и не смогу дать много. Но свитков и зелий не пожалею.",38794,null],[38797,"2026-06-11T16:32:35",11,"— Рад что мы смогли вернуть меч в руки его истинного хозяина, жаль что из-за этого пришлось рисковать жизнями..",38793,null],[38798,"2026-06-11T16:32:49",11,"// я не про наши если что",36440,null],[38799,"2026-06-11T16:33:14",5,"— О, интересная бумага, смотри, чтобы самому не попасть... Ты ведь скрывал лицо, когда поджигал дом?",38795,null],[38800,"2026-06-11T16:33:51",11,"— Та женщина видела его точно",36440,null],[38801,"2026-06-11T16:34:07",11,"— Да и нас видел как минимум стражник в комнате.. если он ещё жив",36440,null],[38802,"2026-06-11T16:34:32",31,"он был в эпицентре пожара. думаю, он уже ничего не расскажет",38801,null],[38803,"2026-06-11T16:35:03",11,"Иштар вздыхает, вы видите что это морально давит на него и он больше не хочет ничего говорить на эту тему",36440,null],[38804,"2026-06-11T16:35:04",5,"— Если никто не погиб, то про вас быстро забудут. А вот убийц в Аннеже не прощают.",38801,null],[38805,"2026-06-11T16:35:14",10,"-Да ничего страшногооо) я ведь маленького роста эльф с вида... Поменяю одежду да вернусь к своему росту и все хорошо",36440,null],[38806,"2026-06-11T16:35:15",9,"//Хорошо что почти всё было во тьме, наши лица мб видел тот страж которого об стену кинул. Но не факт что он точно запомнил ведь точно было больно, ещё и сказал ему \"заговоришь — умрёшь\"",36440,null],[38808,"2026-06-11T16:36:11",9,"//Бля, тот стражник мог и сгореть в теории, не факт что он встал и ушёл вовремя",36440,null],[38809,"2026-06-11T16:36:27",5,"Юноша думает, что делать с добычей. Наконец он приходит к решению. — Вы трое получите награду от меня, а вещички Рури я как-то пристрою и отдам золото.",36440,null],[38810,"2026-06-11T16:36:45",5,"// его прибежавший стражник вытаскивал из огня",38808,null],[38811,"2026-06-11T16:37:00",9,"//Збс",36440,null],[38812,"2026-06-11T16:37:00",10,"-Вот и ладушки) если что я буду 2.5 метров и в платье женском) ты не перепутаешь в отличие от других",38809,null],[38813,"2026-06-11T16:37:39",10,"//кста арт вышел крутой) жаль не оценили)",36440,null],[38814,"2026-06-11T16:38:35",5,"Карс вытаскивает золотые монеты и остальное и даёт вам. Рури позже получит кошель с деньгами.",36440,null],[38815,"2026-06-11T16:38:44",5,"// окей, тогда это конец и я считаю лут",36440,null],[38816,"2026-06-11T16:40:55",9,"Так, отзыв",36440,null],[38817,"2026-06-11T16:41:18",10,"спасибо) было забавно и интересно. п.с. Бабка ебаная я её найду",36440,null],[38818,"2026-06-11T16:41:34",11,"Я приготовлю убежище для нее 🥹",38817,null],[38819,"2026-06-11T16:41:58",9,"В целом, жваво вышло, опасность чувствовалась, но по ходам не ходили. С бабкой вообще сюр, у Рури отдельное проклятие на бабок и проблеммы похоже)",36440,null],[38820,"2026-06-11T16:42:26",10,"с ходами согласен надо было инициативу делать когда стражника надали бить",36440,null],[38821,"2026-06-11T16:42:40",11,"Мне понравилось что два варианта события подготовил \nНу что бы пробраться через крышу или пройти внутри",36440,null],[38822,"2026-06-11T16:43:15",9,"А таз збс всё. Как игрок за перса доволен, тупо использовал все абилки и мне дали крутоотыграть волшебную стрелу)",36440,null],[38823,"2026-06-11T16:44:12",9,"У меня ток 1 ячейка осталась и 1 сила могилы чтобы в мгновение не упасть в 0 если кокнут. Хотя, даже спрыгнув получил 0 урона. Збс считаю)))",36440,null],[38824,"2026-06-11T16:44:41",9,"Укажи что у тебя фирболг (вариант морденкаина) и почитай его)",38820,null],[38825,"2026-06-11T16:45:20",10,"та я почитал))",36440,null],[38826,"2026-06-11T16:46:09",9,"У меня голиаф тоже кста",36440,null],[38827,"2026-06-11T16:46:12",9,"Надо уточнить",36440,null],[38828,"2026-06-11T16:47:44",9,"В целом, на удивленте быстрая игра, мне нарится ^^",36440,null],[38829,"2026-06-11T16:48:00",10,"все я в магаз) Ребят спасибо за игру. Без ебучих отходов каждые пару минут и быстро ровно отыграли)",36440,null],[38831,"2026-06-11T16:53:52",5,"Каждый получает 600 опыта: 300 опыта за квест, ещё 300 за социалку.\nХард ещё 25 опыта за красование на крыше.\n\nОт Карса герои (кроме Рури) получают:\n20 зм каждый\n1 зелье лечения каждый\n3 свитка заклинаний: прыжок, уменьшение, приказ: убегай\n\nИштар получает чешуйчатый доспех\n\nРури позже получает толстый кошель с кучей серебряных монет. В сумме набирается 30 зм. Он понимает, что его жутко обсчитали.\nРури +кольцо https://dnd.su/items/6734-ring-of-the-orator/\n\nКаждый герой полчуил небольшой медальон от Карса и может сохранить как личный предмет.\nМедальон Аннежа.\nС одной стороны выгравирована миниатюра города и надпись Аннежь внизу, с другой — большая буква К с двумя засечками на противоположных концах.\nМожет быть полезным при взаимодействии с преступными организациями Аннежа.",36440,null],[38832,"2026-06-11T16:55:46",5,"Спасибо за отзывы, мне понравилось, что все были активны и закончили бодро квест!",36440,null],[38835,"2026-06-11T16:57:35",23,"Это я так к слову вспомнил его//",36440,null],[38837,"2026-06-11T16:58:28",10,"можно еще 120 опыта за поджог по братски?)) до 3го уровня не хватает каплю",36440,null],[38838,"2026-06-11T16:58:51",10,"а не там больше чуть 210 ошибачка",36440,null],[38839,"2026-06-11T16:58:55",9,"И так нам с лихвой отвалили",36440,null],[38840,"2026-06-11T16:59:06",5,"// ты первого уровня же",38837,null],[38841,"2026-06-11T16:59:06",10,"та я думал каплю надо а надо целый квест",36440,null],[38842,"2026-06-11T16:59:08",10,"забей)",36440,null],[38843,"2026-06-11T16:59:14",9,"По мне так лишнего, 2 уровня сразу хош?)))",36440,null],[38844,"2026-06-11T16:59:26",10,"у меня был почти 2й уровень",38840,null],[38845,"2026-06-11T16:59:30",10,"190 опыта было)",36440,null],[38846,"2026-06-11T16:59:38",9,"И что, так вышло ^^",36440,null],[38847,"2026-06-11T16:59:43",9,"Квест то лайтовый",36440,null],[38848,"2026-06-11T16:59:51",10,"та ничего) за спрос денег не берут",36440,null],[38849,"2026-06-11T17:00:09",9,"Свитки заклинаний господа",36440,null],[38850,"2026-06-11T17:00:35",9,"Я хочу прыжок взять или щелье лечения, а вы?",36440,null],[38851,"2026-06-11T17:00:47",9,"Типа нас 4 а предметов тож 4",36440,null],[38852,"2026-06-11T17:01:29",23,"там написано то что каждому по одному....",36440,null],[38853,"2026-06-11T17:01:32",9,"А, рури отдельно",36440,null],[38854,"2026-06-11T17:01:34",23,"каждому зелье лечения",36440,null],[38855,"2026-06-11T17:01:55",9,"Хочу прыжок, или хз, что вы берёте?",36440,null],[38856,"2026-06-11T17:03:28",31,"мне без разницы",36440,null],[38857,"2026-06-11T17:03:39",31,"заберу что останется",36440,null],[38858,"2026-06-11T17:03:44",5,"// каждому зелье лечения",38851,null],[38859,"2026-06-11T17:04:28",10,"Меня тоже считают чтоль?",36440,null],[38860,"2026-06-11T17:04:39",9,"Похоже нет, тебе колечко",36440,null],[38861,"2026-06-11T17:04:43",5,"// не, тебе золото и кольцо",38859,null],[38862,"2026-06-11T17:04:45",9,"Оно попизже будет",36440,null],[38863,"2026-06-11T17:05:12",10,"Написано же это ваш лут на троих",36440,null],[38864,"2026-06-11T17:05:21",10,"Ага но я честно спиздил)",38862,null],[38865,"2026-06-11T17:05:43",9,"@Ashenchampion не против что возьму свиток прыжка?",36440,null],[38866,"2026-06-11T17:05:50",11,"Бери",36440,null],[38867,"2026-06-11T17:05:56",9,"Хорошо",36440,null],[38868,"2026-06-11T17:06:03",11,"Приказ возьму бабке отдам когда Рури за ней придет",36440,null],[38869,"2026-06-11T17:42:05",31,"Так, а мне то какой свиток ал итогу?",36440,null],[38870,"2026-06-11T17:42:30",31,"А понял, уменьшение",36440,null],[38871,"2026-06-11T17:42:49",9,"Кому надо продать свитки — говоритес помогу",36440,null],[38872,"2026-06-11T17:42:58",31,"Мне",38871,null],[38873,"2026-06-11T17:42:59",9,"В бросках если чо",36440,null]]);
